(function () {
  var OR = (window.OR = window.OR || {}); OR.qa = OR.qa || [];
  OR.qa.push(
    {"id": "cs2-aho-corasick", "title": "Aho-Corasick (multi-pattern search)", "cat": "Strings: matching", "q": ["what is Aho-Corasick", "explain Aho-Corasick", "how does Aho-Corasick work", "Aho-Corasick in python", "implement Aho-Corasick", "Aho-Corasick code", "when to use Aho-Corasick", "aho corasick vs kmp", "search many words in a text at once"], "tags": "aho corasick multiple pattern string matching trie failure links automaton dictionary search", "a": "Aho-Corasick finds every occurrence of many patterns in one pass over the text. Build a trie of the patterns, add failure links (the longest proper suffix that is also a trie prefix) with BFS, then walk the text following links on mismatch. Use it for dictionary matching, filters and keyword search.", "code": {"py": "from collections import deque\n\ndef aho_corasick(text, patterns):\n    \"\"\"Return sorted (start, pattern_index) for every occurrence of every non-empty pattern.\"\"\"\n    nxt, fail, out = [{}], [0], [[]]\n    for pi, p in enumerate(patterns):\n        if not p:\n            continue\n        s = 0\n        for ch in p:\n            if ch not in nxt[s]:\n                nxt.append({}); fail.append(0); out.append([])\n                nxt[s][ch] = len(nxt) - 1\n            s = nxt[s][ch]\n        out[s].append(pi)\n    q = deque(nxt[0].values())\n    while q:\n        u = q.popleft()\n        for ch, v in nxt[u].items():\n            f = fail[u]\n            while f and ch not in nxt[f]:\n                f = fail[f]\n            fail[v] = nxt[f].get(ch, 0)\n            out[v] = out[v] + out[fail[v]]      # inherit matches of the suffix state\n            q.append(v)\n    res, s = [], 0\n    for i, ch in enumerate(text):\n        while s and ch not in nxt[s]:\n            s = fail[s]\n        s = nxt[s].get(ch, 0)\n        for pi in out[s]:\n            res.append((i - len(patterns[pi]) + 1, pi))\n    return sorted(res)\n\nprint(aho_corasick(\"ushers\", [\"he\", \"she\", \"his\", \"hers\"]))  # [(1, 1), (2, 0), (2, 3)]"}, "check": "import random\nassert aho_corasick(\"ushers\", [\"he\", \"she\", \"his\", \"hers\"]) == [(1, 1), (2, 0), (2, 3)]\nassert aho_corasick(\"abc\", []) == [] and aho_corasick(\"\", [\"a\"]) == []\nfor _ in range(300):\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 12)))\n    ps = [\"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 4))) for _ in range(random.randint(1, 4))]\n    exp = sorted((i, k) for k, p in enumerate(ps) for i in range(len(t) - len(p) + 1) if t.startswith(p, i))\n    assert aho_corasick(t, ps) == exp, (t, ps)", "more": "- Invariant: the state after reading text[:i] is the longest suffix of that text which is a trie prefix; the failure link jumps to the next shorter one.\n- Merging `out` along failure links reports patterns that are suffixes of other patterns (like \"he\" inside \"she\").\n- The number of matches can be huge (overlapping patterns); that output size is not hidden in the bound.\n- For a single pattern use KMP; for a few patterns of equal length Rabin-Karp is simpler.", "cx": "Build O(total pattern length) with dict transitions; search O(n + number of matches). Space O(total pattern length).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-boyer-moore", "title": "Boyer-Moore (bad character and good suffix)", "cat": "Strings: matching", "q": ["what is Boyer-Moore", "explain Boyer-Moore", "how does Boyer-Moore work", "Boyer-Moore in python", "implement Boyer-Moore", "Boyer-Moore code", "when to use Boyer-Moore", "boyer moore bad character rule", "boyer moore good suffix rule", "boyer moore vs kmp"], "tags": "boyer moore string search bad character good suffix right to left skip sublinear", "a": "Boyer-Moore compares the pattern right to left and, on a mismatch, shifts by the larger of two rules: the bad-character rule (align the text char with its last occurrence in the pattern) and the good-suffix rule (align the matched suffix with another copy). It often skips most of the text, so it is fast on long patterns.", "code": {"py": "def boyer_moore(t, p):\n    \"\"\"Start indices of all occurrences of p in t.\"\"\"\n    n, m = len(t), len(p)\n    if m == 0:\n        return list(range(n + 1))\n    last = {c: i for i, c in enumerate(p)}\n    shift, border = [0] * (m + 1), [0] * (m + 1)\n    i, j = m, m + 1\n    border[i] = j\n    while i > 0:                                   # strong good-suffix preprocessing\n        while j <= m and p[i - 1] != p[j - 1]:\n            if shift[j] == 0:\n                shift[j] = j - i\n            j = border[j]\n        i -= 1; j -= 1\n        border[i] = j\n    j = border[0]\n    for i in range(m + 1):\n        if shift[i] == 0:\n            shift[i] = j\n        if i == j:\n            j = border[j]\n    res, s = [], 0\n    while s <= n - m:\n        j = m - 1\n        while j >= 0 and p[j] == t[s + j]:\n            j -= 1\n        if j < 0:\n            res.append(s)\n            s += shift[0]\n        else:\n            s += max(shift[j + 1], j - last.get(t[s + j], -1))\n    return res\n\nprint(boyer_moore(\"abababab\", \"abab\"))  # [0, 2, 4]"}, "check": "import random\nassert boyer_moore(\"abababab\", \"abab\") == [0, 2, 4] and boyer_moore(\"abc\", \"\") == [0, 1, 2, 3]\nfor _ in range(500):\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 14)))\n    p = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 5)))\n    assert boyer_moore(t, p) == [i for i in range(len(t) - len(p) + 1) if t.startswith(p, i)], (t, p)", "more": "- Both rules are safe shifts (never skip a match); the max of the two is used.\n- With the good-suffix rule the search is linear when the pattern does not occur; with many occurrences the plain version can still reach O(nm) (the Galil rule fixes that).\n- On tiny alphabets or short patterns the overhead often loses to `str.find`.\n- Closest alternatives: Horspool (bad character only) and KMP (guaranteed linear).", "cx": "Preprocess O(m). Search best case about O(n/m), typical sublinear, worst case O(nm) in this version. Space O(m + alphabet).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-horspool", "title": "Boyer-Moore-Horspool", "cat": "Strings: matching", "q": ["what is Boyer-Moore-Horspool", "explain Boyer-Moore-Horspool", "how does Boyer-Moore-Horspool work", "Boyer-Moore-Horspool in python", "implement Boyer-Moore-Horspool", "Boyer-Moore-Horspool code", "when to use Boyer-Moore-Horspool", "horspool vs boyer moore"], "tags": "horspool boyer moore horspool bad character shift table simple fast substring search", "a": "Horspool is the simplified Boyer-Moore: compare the window, then shift by a table lookup on the text character under the last pattern position. The table stores, for each character, its distance from the end of the pattern (excluding the last char). It is short to code and fast on average.", "code": {"py": "def horspool(t, p):\n    n, m = len(t), len(p)\n    if m == 0:\n        return list(range(n + 1))\n    shift = {c: m - 1 - i for i, c in enumerate(p[:-1])}   # last occurrence wins\n    res, s = [], 0\n    while s <= n - m:\n        if t[s:s + m] == p:\n            res.append(s)\n        s += shift.get(t[s + m - 1], m)\n    return res\n\nprint(horspool(\"here is a simple example\", \"example\"))  # [17]"}, "check": "import random\nassert horspool(\"here is a simple example\", \"example\") == [17]\nassert horspool(\"aaaa\", \"aa\") == [0, 1, 2] and horspool(\"ab\", \"abc\") == []\nfor _ in range(500):\n    t = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 14)))\n    p = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 4)))\n    assert horspool(t, p) == [i for i in range(len(t) - len(p) + 1) if t.startswith(p, i)], (t, p)", "more": "- The shift is safe because the char under the last pattern position must line up with its rightmost earlier occurrence in the pattern (or skip the whole window).\n- Excluding the last pattern char from the table matters; otherwise shifts would be 0.\n- Worst case O(nm), for example text `aaaa...` with pattern `baaa`.\n- Closest alternatives: Sunday (looks one char past the window), full Boyer-Moore, KMP.", "cx": "Preprocess O(m). Search average about O(n/m) on random text, worst case O(nm). Space O(alphabet).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-sunday", "title": "Sunday algorithm (Quick Search)", "cat": "Strings: matching", "q": ["what is Sunday algorithm", "explain Sunday algorithm", "how does Sunday algorithm work", "Sunday algorithm in python", "implement Sunday algorithm", "Sunday algorithm code", "when to use Sunday algorithm", "quick search algorithm"], "tags": "sunday quick search substring search shift table next character after window", "a": "The Sunday algorithm checks the window, then looks at the character just after it. If that char is not in the pattern, jump past it (shift m+1); otherwise align its last occurrence in the pattern with it. Easy to write and often faster than Horspool on real text.", "code": {"py": "def sunday(t, p):\n    n, m = len(t), len(p)\n    if m == 0:\n        return list(range(n + 1))\n    shift = {c: m - i for i, c in enumerate(p)}      # distance from char to one past pattern end\n    res, s = [], 0\n    while s <= n - m:\n        if t[s:s + m] == p:\n            res.append(s)\n        if s + m >= n:\n            break\n        s += shift.get(t[s + m], m + 1)\n    return res\n\nprint(sunday(\"substring searching algorithm\", \"search\"))  # [10]"}, "check": "import random\nassert sunday(\"substring searching algorithm\", \"search\") == [10]\nassert sunday(\"aaaa\", \"aa\") == [0, 1, 2] and sunday(\"\", \"a\") == []\nfor _ in range(500):\n    t = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 14)))\n    p = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 4)))\n    assert sunday(t, p) == [i for i in range(len(t) - len(p) + 1) if t.startswith(p, i)], (t, p)", "more": "- Safe shift: any match that starts before the next alignment must contain text[s+m], so its position in the pattern decides the move.\n- Maximum shift is m+1, one more than Horspool.\n- Worst case is still quadratic; no linear guarantee.\n- Closest alternative: Horspool; for guaranteed linear time use KMP.", "cx": "Preprocess O(m). Search average about O(n/m), worst case O(nm). Space O(alphabet).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-rabin-karp-multi", "title": "Rabin-Karp for multiple patterns", "cat": "Strings: matching", "q": ["what is multi-pattern Rabin-Karp", "explain multi-pattern Rabin-Karp", "how does multi-pattern Rabin-Karp work", "multi-pattern Rabin-Karp in python", "implement multi-pattern Rabin-Karp", "multi-pattern Rabin-Karp code", "when to use multi-pattern Rabin-Karp", "search for many substrings with rolling hash", "plagiarism detection rolling hash"], "tags": "rabin karp multiple patterns rolling hash set same length plagiarism detection", "a": "For several patterns of the same length L, hash every pattern into a table, then slide one rolling hash over the text and look up each window. A hit is verified by direct comparison. Cost is one pass for any number of patterns of one length.", "code": {"py": "def rk_multi(text, patterns, base=257, mod=(1 << 61) - 1):\n    \"\"\"All patterns must share one length L >= 1. Returns sorted (start, pattern).\"\"\"\n    if not patterns:\n        return []\n    L = len(patterns[0])\n    assert L >= 1 and all(len(p) == L for p in patterns)\n    def h(s):\n        v = 0\n        for ch in s:\n            v = (v * base + ord(ch)) % mod\n        return v\n    table = {}\n    for p in patterns:\n        table.setdefault(h(p), set()).add(p)\n    if len(text) < L:\n        return []\n    top = pow(base, L - 1, mod)\n    cur, res = h(text[:L]), []\n    for i in range(len(text) - L + 1):\n        w = text[i:i + L]\n        if cur in table and w in table[cur]:       # verify to rule out collisions\n            res.append((i, w))\n        if i + L < len(text):\n            cur = ((cur - ord(text[i]) * top) * base + ord(text[i + L])) % mod\n    return sorted(res)\n\nprint(rk_multi(\"abcabd\", [\"ab\", \"bd\"]))  # [(0, 'ab'), (3, 'ab'), (4, 'bd')]"}, "check": "import random\nassert rk_multi(\"abcabd\", [\"ab\", \"bd\"]) == [(0, \"ab\"), (3, \"ab\"), (4, \"bd\")]\nassert rk_multi(\"a\", [\"ab\"]) == [] and rk_multi(\"abc\", []) == []\nfor _ in range(300):\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 14)))\n    L = random.randint(1, 3)\n    ps = [\"\".join(random.choice(\"ab\") for _ in range(L)) for _ in range(3)]\n    exp = sorted((i, t[i:i + L]) for i in range(len(t) - L + 1) if t[i:i + L] in ps)\n    assert rk_multi(t, ps) == exp, (t, ps)", "more": "- One rolling hash serves all patterns because they have equal length; different lengths need one pass (or one table) per length.\n- Always verify the window after a hash hit; the hash only filters.\n- Use a large modulus (2^61-1) or double hashing to make collisions negligible.\n- When lengths differ, use Aho-Corasick instead.", "cx": "Preprocess O(kL) for k patterns. Search expected O(nL) for the slice compares of hits plus O(n) hashing; worst case O(nL) with many collisions. Space O(kL).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-suffix-array", "title": "Suffix array (naive and prefix doubling)", "cat": "Strings: structures", "q": ["what is suffix array", "explain suffix array", "how does suffix array work", "suffix array in python", "implement suffix array", "suffix array code", "when to use suffix array", "build suffix array", "sort all suffixes of a string", "suffix array vs suffix tree"], "tags": "suffix array prefix doubling sorting suffixes O(n log^2 n) banana substring search", "a": "A suffix array lists the start indices of all suffixes in sorted order. The naive build sorts the n suffix strings (O(n^2 log n) worst case). Prefix doubling sorts by the first 2^k characters using ranks from the previous round, giving O(n log^2 n) with a comparison sort. It supports substring search by binary search.", "code": {"py": "def suffix_array(s):\n    \"\"\"Prefix doubling: sort suffixes by their first 1, 2, 4, ... characters.\"\"\"\n    n = len(s)\n    if n == 0:\n        return []\n    sa, rank, k = list(range(n)), [ord(c) for c in s], 1\n    while True:\n        key = lambda i: (rank[i], rank[i + k] if i + k < n else -1)\n        sa.sort(key=key)\n        new = [0] * n\n        for j in range(1, n):\n            new[sa[j]] = new[sa[j - 1]] + (key(sa[j - 1]) < key(sa[j]))\n        rank = new\n        if rank[sa[-1]] == n - 1:\n            return sa\n        k *= 2\n\ndef contains(s, sa, pat):\n    lo, hi = 0, len(sa)\n    while lo < hi:                       # first suffix whose prefix >= pat\n        mid = (lo + hi) // 2\n        if s[sa[mid]:sa[mid] + len(pat)] < pat: lo = mid + 1\n        else: hi = mid\n    return lo < len(sa) and s[sa[lo]:sa[lo] + len(pat)] == pat\n\nprint(suffix_array(\"banana\"))  # [5, 3, 1, 0, 4, 2]"}, "check": "import random\ndef brute_sa(s): return sorted(range(len(s)), key=lambda i: s[i:])\ndef rnd(n, a=\"ab\"): return \"\".join(random.choice(a) for _ in range(n))\n\nassert suffix_array(\"banana\") == [5, 3, 1, 0, 4, 2] and suffix_array(\"\") == [] and suffix_array(\"a\") == [0]\nfor _ in range(300):\n    s = rnd(random.randint(1, 20), \"ab\" if random.random() < .5 else \"abc\")\n    sa = suffix_array(s)\n    assert sa == brute_sa(s), s\n    p = rnd(random.randint(1, 3))\n    assert contains(s, sa, p) == (p in s)", "more": "- Round k ranks suffixes by their first 2^k chars; the key (rank[i], rank[i+k]) combines two already-ranked halves.\n- Stop once all ranks are distinct (at most ceil(log2 n) rounds).\n- Replace the comparison sort with radix sort for O(n log n); SA-IS or DC3 give O(n).\n- Python tip: the naive `sorted(range(n), key=lambda i: s[i:])` is fine for short strings but copies O(n^2) characters.\n- Alternatives: suffix automaton (online, also small), suffix tree (more memory).", "cx": "Naive O(n^2 log n) worst case. Prefix doubling with sort: O(n log^2 n) time, O(n) space. Search for a pattern of length m: O(m log n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-lcp-kasai", "title": "LCP array (Kasai)", "cat": "Strings: structures", "q": ["what is Kasai LCP array", "explain Kasai LCP array", "how does Kasai LCP array work", "Kasai LCP array in python", "implement Kasai LCP array", "Kasai LCP array code", "when to use Kasai LCP array", "height array suffix array", "longest common prefix of suffixes"], "tags": "kasai lcp array longest common prefix suffix array linear time height array", "a": "Kasai's algorithm builds the LCP array (longest common prefix of neighbouring suffixes in suffix-array order) in O(n) given the suffix array. Walk suffixes in text order; the LCP of suffix i+1 with its predecessor is at least the one for suffix i minus one, so the match length h only moves forward amortized.", "code": {"py": "def suffix_array(s):\n    \"\"\"Prefix doubling: sort suffixes by their first 1, 2, 4, ... characters.\"\"\"\n    n = len(s)\n    if n == 0:\n        return []\n    sa, rank, k = list(range(n)), [ord(c) for c in s], 1\n    while True:\n        key = lambda i: (rank[i], rank[i + k] if i + k < n else -1)\n        sa.sort(key=key)\n        new = [0] * n\n        for j in range(1, n):\n            new[sa[j]] = new[sa[j - 1]] + (key(sa[j - 1]) < key(sa[j]))\n        rank = new\n        if rank[sa[-1]] == n - 1:\n            return sa\n        k *= 2\n\ndef kasai(s, sa):\n    \"\"\"lcp[i] = longest common prefix of suffixes sa[i-1] and sa[i]; lcp[0] = 0.\"\"\"\n    n = len(s)\n    rank = [0] * n\n    for i, p in enumerate(sa):\n        rank[p] = i\n    lcp, h = [0] * n, 0\n    for i in range(n):\n        if rank[i] > 0:\n            j = sa[rank[i] - 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rank[i]] = h\n            if h:\n                h -= 1\n        else:\n            h = 0\n    return lcp\n\nprint(kasai(\"banana\", suffix_array(\"banana\")))  # [0, 1, 3, 0, 0, 2]"}, "check": "import random\ndef brute_sa(s): return sorted(range(len(s)), key=lambda i: s[i:])\ndef rnd(n, a=\"ab\"): return \"\".join(random.choice(a) for _ in range(n))\n\ndef lcp2(a, b):\n    k = 0\n    while k < min(len(a), len(b)) and a[k] == b[k]: k += 1\n    return k\nassert kasai(\"banana\", suffix_array(\"banana\")) == [0, 1, 3, 0, 0, 2]\nfor _ in range(300):\n    s = rnd(random.randint(1, 18))\n    sa = suffix_array(s)\n    exp = [0] + [lcp2(s[sa[i - 1]:], s[sa[i]:]) for i in range(1, len(s))]\n    assert kasai(s, sa) == exp, s", "more": "- Key fact: if suffix i has LCP h with its predecessor in sorted order, suffix i+1 has LCP at least h-1 with its own predecessor.\n- So `h` only decreases by 1 per step and can increase at most 2n times in total.\n- Use the LCP array with the suffix array for: longest repeated substring, distinct substring count, longest common substring of two strings.\n- A range-minimum query over lcp gives the LCP of any two suffixes.", "cx": "Time O(n) (excluding the suffix array build). Space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-suffix-automaton", "title": "Suffix automaton (build and count distinct substrings)", "cat": "Strings: structures", "q": ["what is suffix automaton", "explain suffix automaton", "how does suffix automaton work", "suffix automaton in python", "implement suffix automaton", "suffix automaton code", "when to use suffix automaton", "count distinct substrings with suffix automaton", "sam string algorithm"], "tags": "suffix automaton sam suffix link distinct substrings online construction smallest automaton", "a": "A suffix automaton is the smallest DFA that accepts exactly the suffixes of a string; it has at most 2n states and is built online one character at a time. Each state groups substrings with the same end positions; the number of distinct substrings is the sum of len[v] - len[link[v]].", "code": {"py": "class SuffixAutomaton:\n    def __init__(self, s=\"\"):\n        self.nxt, self.link, self.len, self.last = [{}], [-1], [0], 0\n        for c in s:\n            self.add(c)\n\n    def add(self, c):\n        cur = len(self.nxt)\n        self.nxt.append({}); self.len.append(self.len[self.last] + 1); self.link.append(0)\n        p = self.last\n        while p != -1 and c not in self.nxt[p]:\n            self.nxt[p][c] = cur\n            p = self.link[p]\n        if p != -1:\n            q = self.nxt[p][c]\n            if self.len[p] + 1 == self.len[q]:\n                self.link[cur] = q\n            else:\n                cl = len(self.nxt)                       # clone q with a shorter length\n                self.nxt.append(dict(self.nxt[q])); self.len.append(self.len[p] + 1); self.link.append(self.link[q])\n                while p != -1 and self.nxt[p].get(c) == q:\n                    self.nxt[p][c] = cl\n                    p = self.link[p]\n                self.link[q] = self.link[cur] = cl\n        self.last = cur\n\n    def contains(self, t):\n        v = 0\n        for c in t:\n            if c not in self.nxt[v]:\n                return False\n            v = self.nxt[v][c]\n        return True\n\n    def distinct_substrings(self):\n        return sum(self.len[v] - self.len[self.link[v]] for v in range(1, len(self.nxt)))\n\nprint(SuffixAutomaton(\"abcbc\").distinct_substrings())  # 12"}, "check": "import random\nassert SuffixAutomaton(\"abcbc\").distinct_substrings() == 12 and SuffixAutomaton(\"\").distinct_substrings() == 0\nfor _ in range(300):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 14)))\n    sam = SuffixAutomaton(s)\n    subs = {s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)}\n    assert sam.distinct_substrings() == len(subs), s\n    assert len(sam.nxt) <= max(1, 2 * len(s))\n    t = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 4)))\n    assert sam.contains(t) == (t in s)", "more": "- State v represents all substrings that end at the same set of positions; their lengths run from len[link[v]]+1 to len[v].\n- Cloning keeps those equivalence classes correct when a new character splits a state.\n- Occurrence counts: mark non-clone states with 1, then sum along suffix links in decreasing len order.\n- Python memory: dict per state is heavy; for n over about 10^6 use arrays or a suffix array.\n- Alternative: suffix array + LCP (simpler, no automaton).", "cx": "Build O(n) amortized for a fixed alphabet (dict transitions: expected O(n)). States at most 2n-1, transitions at most 3n-4. Space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-suffix-trie-tree", "title": "Suffix trie and suffix tree (Ukkonen overview)", "cat": "Strings: structures", "q": ["what is suffix tree", "explain suffix tree", "how does suffix tree work", "suffix tree in python", "implement suffix tree", "suffix tree code", "when to use suffix tree", "ukkonen algorithm", "naive suffix trie", "suffix tree vs suffix array"], "tags": "suffix tree suffix trie ukkonen compressed trie of suffixes naive build substring search", "a": "A suffix trie inserts every suffix of s$ into a trie, so any substring query walks one path; it takes O(n^2) space. A suffix tree compresses unary chains to get O(n) nodes, and Ukkonen builds it online in O(n). This entry is an overview with a working naive suffix trie; Ukkonen itself is not shown.", "code": {"py": "class SuffixTrie:\n    \"\"\"Naive O(n^2) suffix trie of s + '$'. Educational: the suffix tree is this trie with chains compressed.\"\"\"\n    def __init__(self, s):\n        self.root = {}\n        t = s + \"$\"\n        for i in range(len(t)):\n            node = self.root\n            for c in t[i:]:\n                node = node.setdefault(c, {})\n\n    def contains(self, p):\n        node = self.root\n        for c in p:\n            if c not in node:\n                return False\n            node = node[c]\n        return True\n\n    def count_nodes(self):\n        stack, n = [self.root], 0\n        while stack:\n            d = stack.pop(); n += len(d); stack.extend(d.values())\n        return n\n\nst = SuffixTrie(\"banana\")\nprint(st.contains(\"nan\"), st.contains(\"nab\"))  # True False"}, "check": "import random\nst = SuffixTrie(\"banana\")\nassert st.contains(\"nan\") and not st.contains(\"nab\") and st.contains(\"\") and st.contains(\"banana\")\nfor _ in range(200):\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 12)))\n    st = SuffixTrie(s)\n    for _ in range(5):\n        p = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 4)))\n        assert st.contains(p) == (p in s)\n    assert st.count_nodes() >= len(s) + 1", "more": "- The terminal `$` makes every suffix end at a leaf, so no suffix is a prefix of another.\n- Suffix tree = suffix trie with each path of single-child nodes replaced by one edge labelled by an (start, end) slice of s; that is why it has at most 2n nodes.\n- Ukkonen's idea: extend the tree one character at a time using suffix links and an active point, with implicit extensions for the leaf edges.\n- In practice use a suffix array + LCP or a suffix automaton; they are far shorter to code.", "cx": "Naive trie: O(n^2) time and space. Suffix tree via Ukkonen: O(n) time and space for a fixed alphabet. Query for pattern length m: O(m).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-longest-repeated-substring", "title": "Longest repeated substring (suffix array + LCP)", "cat": "Strings: structures", "q": ["what is longest repeated substring", "explain longest repeated substring", "how does longest repeated substring work", "longest repeated substring in python", "implement longest repeated substring", "longest repeated substring code", "when to use longest repeated substring", "longest repeated substring in a string", "longest substring that appears twice"], "tags": "longest repeated substring longest duplicated substring suffix array lcp maximum", "a": "The longest substring that appears at least twice is the longest common prefix of two adjacent suffixes in sorted order, so build the suffix array and LCP array and take the maximum LCP. The substring is s[sa[i]: sa[i] + lcp[i]] at the best position i.", "code": {"py": "def suffix_array(s):\n    \"\"\"Prefix doubling: sort suffixes by their first 1, 2, 4, ... characters.\"\"\"\n    n = len(s)\n    if n == 0:\n        return []\n    sa, rank, k = list(range(n)), [ord(c) for c in s], 1\n    while True:\n        key = lambda i: (rank[i], rank[i + k] if i + k < n else -1)\n        sa.sort(key=key)\n        new = [0] * n\n        for j in range(1, n):\n            new[sa[j]] = new[sa[j - 1]] + (key(sa[j - 1]) < key(sa[j]))\n        rank = new\n        if rank[sa[-1]] == n - 1:\n            return sa\n        k *= 2\n\ndef kasai(s, sa):\n    \"\"\"lcp[i] = longest common prefix of suffixes sa[i-1] and sa[i]; lcp[0] = 0.\"\"\"\n    n = len(s)\n    rank = [0] * n\n    for i, p in enumerate(sa):\n        rank[p] = i\n    lcp, h = [0] * n, 0\n    for i in range(n):\n        if rank[i] > 0:\n            j = sa[rank[i] - 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rank[i]] = h\n            if h:\n                h -= 1\n        else:\n            h = 0\n    return lcp\n\ndef longest_repeated(s):\n    if len(s) < 2:\n        return \"\"\n    sa = suffix_array(s)\n    lcp = kasai(s, sa)\n    i = max(range(len(s)), key=lambda k: lcp[k])\n    return s[sa[i]:sa[i] + lcp[i]]\n\nprint(longest_repeated(\"banana\"))  # ana"}, "check": "import random\ndef brute_sa(s): return sorted(range(len(s)), key=lambda i: s[i:])\ndef rnd(n, a=\"ab\"): return \"\".join(random.choice(a) for _ in range(n))\n\ndef brute(s):\n    best = 0\n    for L in range(1, len(s)):\n        if any(s.count(s[i:i + L]) > 0 and s.find(s[i:i + L], i + 1) != -1 for i in range(len(s) - L + 1)):\n            best = L\n    return best\nassert longest_repeated(\"banana\") == \"ana\" and longest_repeated(\"abc\") == \"\" and longest_repeated(\"\") == \"\"\nfor _ in range(300):\n    s = rnd(random.randint(0, 16), \"abc\")\n    r = longest_repeated(s)\n    assert len(r) == brute(s), (s, r)\n    assert r == \"\" or s.find(r) != s.rfind(r) or s.count(r) > 1 or s.find(r, s.find(r) + 1) != -1", "more": "- Any two equal substrings extend to a common prefix of two suffixes, and sorted order puts the best pair next to each other.\n- Occurrences may overlap (\"ana\" in \"banana\"); if overlap is forbidden you need a binary search on length with a non-overlap check.\n- Alternatives: binary search on length + rolling hash (simpler, expected O(n log n)); suffix automaton.", "cx": "Time O(n log^2 n) with this suffix array (O(n) with SA-IS), space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-longest-common-substring", "title": "Longest common substring of two strings", "cat": "Strings: structures", "q": ["what is longest common substring", "explain longest common substring", "how does longest common substring work", "longest common substring in python", "implement longest common substring", "longest common substring code", "when to use longest common substring", "longest common substring vs longest common subsequence", "maximum length of repeated subarray", "longest common substring dp"], "tags": "longest common substring two strings dp contiguous suffix array leetcode 718 maximum length repeated subarray", "a": "Longest common substring needs contiguous matches. DP: cell (i, j) is the length of the common suffix of a[:i] and b[:j], equal to 1 + diagonal if the chars match, else 0; the answer is the maximum cell. A suffix array of a + \"#\" + b with LCP gives O((n+m) log) instead of O(nm).", "code": {"py": "def longest_common_substring(a, b):\n    best, end = 0, 0\n    prev = [0] * (len(b) + 1)\n    for i in range(1, len(a) + 1):\n        cur = [0] * (len(b) + 1)\n        for j in range(1, len(b) + 1):\n            if a[i - 1] == b[j - 1]:\n                cur[j] = prev[j - 1] + 1\n                if cur[j] > best:\n                    best, end = cur[j], i\n        prev = cur\n    return a[end - best:end]\n\nprint(longest_common_substring(\"xabcdy\", \"zabcw\"))  # abc"}, "check": "import random\nassert longest_common_substring(\"xabcdy\", \"zabcw\") == \"abc\" and longest_common_substring(\"abc\", \"xyz\") == \"\"\nassert longest_common_substring(\"\", \"a\") == \"\"\nfor _ in range(300):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 9)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 9)))\n    r = longest_common_substring(a, b)\n    brute = max([j - i for i in range(len(a)) for j in range(i, len(a) + 1) if a[i:j] in b] + [0])\n    assert len(r) == brute and r in a and r in b", "more": "- Contiguity is why a mismatch resets the cell to 0; for subsequences (LCS) it would carry max(left, up) instead.\n- Only the previous row is needed, so space is O(m).\n- Common mistake: returning the largest cell value of the whole table row instead of tracking the global maximum.\n- Faster for huge inputs: generalized suffix automaton or suffix array of a#b.", "cx": "Time O(nm), space O(m) with two rows. Suffix-array approach O((n+m) log^2 (n+m)).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-count-distinct-substrings", "title": "Count distinct substrings", "cat": "Strings: structures", "q": ["what is count distinct substrings", "explain count distinct substrings", "how does count distinct substrings work", "count distinct substrings in python", "implement count distinct substrings", "count distinct substrings code", "when to use count distinct substrings", "number of unique substrings of a string", "distinct substrings of a string"], "tags": "count distinct substrings number of unique substrings suffix array lcp formula n(n+1)/2", "a": "Every substring is a prefix of some suffix. Sorted suffixes contribute n(n+1)/2 prefixes in total, and neighbouring suffixes share lcp[i] of them, so distinct substrings = n(n+1)/2 - sum(lcp). A suffix automaton gives the same count as sum(len[v] - len[link[v]]).", "code": {"py": "def suffix_array(s):\n    \"\"\"Prefix doubling: sort suffixes by their first 1, 2, 4, ... characters.\"\"\"\n    n = len(s)\n    if n == 0:\n        return []\n    sa, rank, k = list(range(n)), [ord(c) for c in s], 1\n    while True:\n        key = lambda i: (rank[i], rank[i + k] if i + k < n else -1)\n        sa.sort(key=key)\n        new = [0] * n\n        for j in range(1, n):\n            new[sa[j]] = new[sa[j - 1]] + (key(sa[j - 1]) < key(sa[j]))\n        rank = new\n        if rank[sa[-1]] == n - 1:\n            return sa\n        k *= 2\n\ndef kasai(s, sa):\n    \"\"\"lcp[i] = longest common prefix of suffixes sa[i-1] and sa[i]; lcp[0] = 0.\"\"\"\n    n = len(s)\n    rank = [0] * n\n    for i, p in enumerate(sa):\n        rank[p] = i\n    lcp, h = [0] * n, 0\n    for i in range(n):\n        if rank[i] > 0:\n            j = sa[rank[i] - 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rank[i]] = h\n            if h:\n                h -= 1\n        else:\n            h = 0\n    return lcp\n\ndef count_distinct(s):\n    n = len(s)\n    return n * (n + 1) // 2 - sum(kasai(s, suffix_array(s))) if n else 0\n\nprint(count_distinct(\"abab\"))  # 7"}, "check": "import random\ndef brute_sa(s): return sorted(range(len(s)), key=lambda i: s[i:])\ndef rnd(n, a=\"ab\"): return \"\".join(random.choice(a) for _ in range(n))\n\nassert count_distinct(\"abab\") == 7 and count_distinct(\"\") == 0 and count_distinct(\"aaa\") == 3\nfor _ in range(300):\n    s = rnd(random.randint(0, 16), \"abc\")\n    assert count_distinct(s) == len({s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)}), s", "more": "- Each repeated prefix is counted again by the next suffix in sorted order, so subtracting the adjacent LCPs removes every duplicate exactly once.\n- To count distinct substrings of each prefix online, use the suffix automaton and add len[cur] - len[link[cur]] after every character.\n- Hashing all substrings in a set is O(n^2) memory; only use for short strings.", "cx": "Time O(n log^2 n) with prefix-doubling SA (O(n) with SA-IS or a suffix automaton). Space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-eertree", "title": "Palindromic tree (eertree)", "cat": "Strings: structures", "q": ["what is palindromic tree", "explain palindromic tree", "how does palindromic tree work", "palindromic tree in python", "implement palindromic tree", "palindromic tree code", "when to use palindromic tree", "count distinct palindromic substrings", "eertree vs manacher"], "tags": "eertree palindromic tree palindrome tree distinct palindromic substrings online suffix palindrome link", "a": "A palindromic tree stores every distinct palindromic substring of a string as a node (a string has at most n of them). Appending a character adds at most one node; suffix links point to the longest proper palindromic suffix. It answers \"how many distinct palindromes\" and counts occurrences in O(n).", "code": {"py": "class Eertree:\n    def __init__(self, s=\"\"):\n        self.len, self.link, self.nxt = [-1, 0], [0, 0], [{}, {}]   # node 0: len -1 root, node 1: len 0 root\n        self.cnt = [0, 0]\n        self.s, self.last = [], 1\n        for c in s:\n            self.add(c)\n\n    def _ok(self, v, i, c):\n        j = i - self.len[v] - 1\n        return j >= 0 and self.s[j] == c\n\n    def add(self, c):\n        self.s.append(c)\n        i = len(self.s) - 1\n        cur = self.last\n        while not self._ok(cur, i, c):\n            cur = self.link[cur]\n        if c in self.nxt[cur]:\n            self.last = self.nxt[cur][c]\n        else:\n            v = len(self.len)\n            self.len.append(self.len[cur] + 2); self.nxt.append({}); self.cnt.append(0)\n            if self.len[v] == 1:\n                self.link.append(1)\n            else:\n                w = self.link[cur]\n                while not self._ok(w, i, c):\n                    w = self.link[w]\n                self.link.append(self.nxt[w][c])\n            self.nxt[cur][c] = v\n            self.last = v\n        self.cnt[self.last] += 1\n\n    def distinct(self):\n        return len(self.len) - 2\n\n    def occurrences(self):\n        \"\"\"Total number of palindromic substrings counted with multiplicity.\"\"\"\n        total = self.cnt[:]\n        for v in range(len(self.len) - 1, 1, -1):   # links point to smaller nodes\n            total[self.link[v]] += total[v]\n        return sum(total[2:])\n\nprint(Eertree(\"eertree\").distinct())  # 7"}, "check": "import random\nassert Eertree(\"eertree\").distinct() == 7 and Eertree(\"\").distinct() == 0 and Eertree(\"aaa\").distinct() == 3\nfor _ in range(300):\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 14)))\n    subs = [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1) if s[i:j] == s[i:j][::-1]]\n    t = Eertree(s)\n    assert t.distinct() == len(set(subs)), s\n    assert t.occurrences() == len(subs), s", "more": "- Node 0 (length -1) and node 1 (length 0) are the two roots; a one-letter palindrome hangs off node 0, a two-letter one off node 1.\n- Why at most one new node per character: the only new palindrome is the longest palindromic suffix; all shorter palindromic suffixes already occurred earlier.\n- Amortized O(1) per character because the suffix-link walk only moves down in length.\n- Alternative: Manacher (finds centres and radii, not distinct palindromes).", "cx": "Time O(n) amortized for a fixed alphabet, space O(n) nodes (at most n + 2).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-lyndon-duval", "title": "Lyndon factorization (Duval)", "cat": "Strings: structures", "q": ["what is Lyndon factorization", "explain Lyndon factorization", "how does Lyndon factorization work", "Lyndon factorization in python", "implement Lyndon factorization", "Lyndon factorization code", "when to use Lyndon factorization", "duval algorithm", "lyndon word"], "tags": "lyndon words duval factorization lexicographically smallest rotation chen fox lyndon", "a": "A Lyndon word is strictly smaller than all its proper rotations (equivalently all its proper suffixes). Every string factors uniquely into a non-increasing sequence of Lyndon words, and Duval's algorithm finds it in O(n) time and O(1) extra space with two pointers.", "code": {"py": "def duval(s):\n    res, i, n = [], 0, len(s)\n    while i < n:\n        j, k = i + 1, i\n        while j < n and s[k] <= s[j]:\n            k = i if s[k] < s[j] else k + 1\n            j += 1\n        while i <= k:                       # emit the repeated Lyndon block\n            res.append(s[i:i + j - k])\n            i += j - k\n    return res\n\nprint(duval(\"banana\"))  # ['b', 'an', 'an', 'a']"}, "check": "import random\ndef is_lyndon(w): return all(w < w[i:] for i in range(1, len(w)))\nassert duval(\"banana\") == [\"b\", \"an\", \"an\", \"a\"] and duval(\"\") == [] and duval(\"aaa\") == [\"a\", \"a\", \"a\"]\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 12)))\n    f = duval(s)\n    assert \"\".join(f) == s and all(is_lyndon(w) for w in f)\n    assert all(f[i] >= f[i + 1] for i in range(len(f) - 1))", "more": "- Pointer k compares the current character with the one a period earlier; equal means the pattern repeats, greater means the whole prefix becomes one longer Lyndon word, smaller ends the block.\n- Uses: smallest rotation (run Duval on s+s and take the last factor start below n), suffix array construction, and the Chen-Fox-Lyndon theorem proofs.\n- The Lyndon factors are non-increasing, which is a quick sanity check.", "cx": "Time O(n), extra space O(1) apart from the output.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-booth-min-rotation", "title": "Minimal rotation (Booth and the two-pointer method)", "cat": "Strings: structures", "q": ["what is lexicographically smallest rotation", "explain lexicographically smallest rotation", "how does lexicographically smallest rotation work", "lexicographically smallest rotation in python", "implement lexicographically smallest rotation", "lexicographically smallest rotation code", "when to use lexicographically smallest rotation", "lexicographically smallest rotation of a string", "canonical form of a cyclic string", "booth algorithm"], "tags": "booth algorithm minimal rotation smallest cyclic shift least rotation lexicographically minimal necklace", "a": "To find the lexicographically smallest rotation of a string, compare candidate start positions i and j with an offset k: on the first difference the larger candidate is eliminated and skipped past the mismatch. This two-pointer method is O(n); Booth's algorithm reaches the same answer with a KMP-style failure function.", "code": {"py": "def min_rotation_index(s):\n    n = len(s)\n    i, j, k = 0, 1, 0\n    while i < n and j < n and k < n:\n        a, b = s[(i + k) % n], s[(j + k) % n]\n        if a == b:\n            k += 1\n            continue\n        if a > b:\n            i += k + 1\n        else:\n            j += k + 1\n        if i == j:\n            j += 1\n        k = 0\n    return min(i, j)\n\ndef min_rotation(s):\n    i = min_rotation_index(s) if s else 0\n    return s[i:] + s[:i]\n\nprint(min_rotation(\"bca\"))  # abc"}, "check": "import random\nassert min_rotation(\"bca\") == \"abc\" and min_rotation(\"\") == \"\" and min_rotation(\"aaa\") == \"aaa\"\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 10)))\n    assert min_rotation(s) == min(s[i:] + s[:i] for i in range(len(s))), s", "more": "- If the candidates tie for k characters and then s[i+k] > s[j+k], every start in i..i+k is worse than the matching start in j..j+k, so i can jump by k+1.\n- When the string is periodic the answer is not unique; this returns the first index.\n- Uses: canonical form for necklaces and cyclic-equality tests (rotations are equal iff their minimal rotations are).\n- Alternative: Duval on s+s, or `min(s[i:]+s[:i])` for short strings (O(n^2)).", "cx": "Time O(n), space O(1) besides the output string.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-period-borders", "title": "String period and borders (prefix function)", "cat": "Strings: matching", "q": ["what is string period and borders", "explain string period and borders", "how does string period and borders work", "string period and borders in python", "implement string period and borders", "string period and borders code", "when to use string period and borders", "smallest period of a string", "repeated substring pattern", "longest border of a string", "longest prefix that is also a suffix"], "tags": "string period border prefix function failure function smallest period repeated substring pattern", "a": "A border is a proper prefix that is also a suffix. With the prefix function pi, the longest border of s is pi[n-1], the smallest period is n - pi[n-1], and all borders are found by repeatedly following pi. s is a repetition of a shorter block exactly when that period divides n.", "code": {"py": "def prefix_function(s):\n    pi = [0] * len(s)\n    for i in range(1, len(s)):\n        k = pi[i - 1]\n        while k and s[i] != s[k]:\n            k = pi[k - 1]\n        if s[i] == s[k]:\n            k += 1\n        pi[i] = k\n    return pi\n\ndef smallest_period(s):\n    return len(s) - prefix_function(s)[-1] if s else 0\n\ndef all_borders(s):\n    pi, res, k = prefix_function(s), [], (prefix_function(s)[-1] if s else 0)\n    while k:\n        res.append(s[:k]); k = pi[k - 1]\n    return res\n\ndef is_repeated_block(s):                 # LeetCode 459\n    p = smallest_period(s)\n    return p < len(s) and len(s) % p == 0\n\nprint(smallest_period(\"abcabcab\"), all_borders(\"abcabcab\"))  # 3 ['abcab', 'ab']"}, "check": "import random\nassert smallest_period(\"abcabcab\") == 3 and all_borders(\"abcabcab\") == [\"abcab\", \"ab\"]\nassert is_repeated_block(\"abab\") and not is_repeated_block(\"aba\") and not is_repeated_block(\"a\")\nfor _ in range(500):\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 12)))\n    n = len(s)\n    per = min(p for p in range(1, n + 1) if all(s[i] == s[i + p] for i in range(n - p)))\n    assert smallest_period(s) == per, s\n    assert all_borders(s) == sorted([s[:k] for k in range(1, n) if s[:k] == s[n - k:]], key=len, reverse=True)\n    assert is_repeated_block(s) == (per < n and n % per == 0)", "more": "- Period p means s[i] == s[i+p] for all valid i; border length b gives period n - b, so the longest border gives the smallest period.\n- Periods that do not divide n exist (\"abcabcab\" has period 3 but is not a full repetition).\n- The same facts hold for the Z-function: p is a period iff z[p] == n - p.\n- Common mistake: using n - pi[-1] as \"repetition count\" without checking divisibility.", "cx": "Time O(n), space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-z-pattern-count", "title": "Z-function applications (count pattern occurrences)", "cat": "Strings: matching", "q": ["what is Z-function pattern counting", "explain Z-function pattern counting", "how does Z-function pattern counting work", "Z-function pattern counting in python", "implement Z-function pattern counting", "Z-function pattern counting code", "when to use Z-function pattern counting", "count occurrences of a pattern with z algorithm", "z algorithm vs kmp"], "tags": "z function z algorithm count occurrences pattern text separator concatenation", "a": "Build the Z-array of pattern + separator + text: z[i] is the length of the longest prefix of that string starting at i. Every position in the text part with z[i] >= len(pattern) is an occurrence. The separator must be a character that occurs in neither string so matches cannot run past the pattern.", "code": {"py": "def z_function(s):\n    n = len(s)\n    z = [0] * n\n    l = r = 0\n    for i in range(1, n):\n        if i < r:\n            z[i] = min(r - i, z[i - l])\n        while i + z[i] < n and s[z[i]] == s[i + z[i]]:\n            z[i] += 1\n        if i + z[i] > r:\n            l, r = i, i + z[i]\n    return z\n\ndef find_all(text, pat):\n    if not pat:\n        return list(range(len(text) + 1))\n    sep = \"\\x00\"                              # assumed not present in the inputs\n    z = z_function(pat + sep + text)\n    m = len(pat)\n    return [i - m - 1 for i in range(m + 1, len(z)) if z[i] >= m]\n\nprint(find_all(\"abababa\", \"aba\"))  # [0, 2, 4]"}, "check": "import random\nassert find_all(\"abababa\", \"aba\") == [0, 2, 4] and find_all(\"abc\", \"d\") == []\nfor _ in range(500):\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 14)))\n    p = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 4)))\n    assert find_all(t, p) == [i for i in range(len(t) - len(p) + 1) if t.startswith(p, i)]", "more": "- The [l, r) window is the rightmost match of a prefix seen so far; inside it z[i] is bounded by the mirrored value z[i-l].\n- Also useful for: counting occurrences of each prefix, string period (z[p] == n-p), checking rotations (pattern in t+t).\n- Alternative: KMP prefix function does the same job; pick whichever you can write from memory.", "cx": "Time O(n + m), space O(n + m).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-radix-tree", "title": "Radix tree (compressed trie)", "cat": "Strings: structures", "q": ["what is radix tree", "explain radix tree", "how does radix tree work", "radix tree in python", "implement radix tree", "radix tree code", "when to use radix tree", "patricia tree", "compressed trie vs trie"], "tags": "radix tree compressed trie patricia tree prefix tree edge labels split", "a": "A radix tree (compressed trie, Patricia-style) stores words in a trie whose edges carry whole strings instead of single characters, so a chain of single-child nodes collapses into one edge. Insertion splits an edge at the first differing character. Lookup and prefix search still cost O(length of the key).", "code": {"py": "class Node:\n    def __init__(self):\n        self.kids = {}        # first char -> (edge label, child Node)\n        self.end = False\n\nclass RadixTree:\n    def __init__(self):\n        self.root = Node()\n\n    def insert(self, w):\n        n = self.root\n        while True:\n            if not w:\n                n.end = True\n                return\n            if w[0] not in n.kids:\n                c = Node(); c.end = True\n                n.kids[w[0]] = (w, c)\n                return\n            lab, c = n.kids[w[0]]\n            k = 0\n            while k < len(lab) and k < len(w) and lab[k] == w[k]:\n                k += 1\n            if k < len(lab):                      # split the edge at k\n                mid = Node()\n                mid.kids[lab[k]] = (lab[k:], c)\n                n.kids[w[0]] = (lab[:k], mid)\n                c = mid\n            n, w = c, w[k:]\n\n    def search(self, w):\n        n = self.root\n        while w:\n            e = n.kids.get(w[0])\n            if not e or not w.startswith(e[0]):\n                return False\n            n, w = e[1], w[len(e[0]):]\n        return n.end\n\n    def with_prefix(self, pre):\n        n, path = self.root, \"\"\n        while pre:\n            e = n.kids.get(pre[0])\n            if not e:\n                return []\n            lab, c = e\n            if pre.startswith(lab):\n                n, path, pre = c, path + lab, pre[len(lab):]\n            elif lab.startswith(pre):\n                n, path, pre = c, path + lab, \"\"\n            else:\n                return []\n        out = []\n        def walk(node, s):\n            if node.end:\n                out.append(s)\n            for lab, c in node.kids.values():\n                walk(c, s + lab)\n        walk(n, path)\n        return sorted(out)\n\nt = RadixTree()\nfor w in [\"romane\", \"romanus\", \"romulus\", \"rubens\"]:\n    t.insert(w)\nprint(t.search(\"romanus\"), t.with_prefix(\"rom\"))  # True ['romane', 'romanus', 'romulus']"}, "check": "import random\nt = RadixTree()\nws = [\"romane\", \"romanus\", \"romulus\", \"rubens\", \"rub\", \"r\"]\nfor w in ws: t.insert(w)\nassert all(t.search(w) for w in ws) and not t.search(\"rom\") and not t.search(\"rubensx\")\nassert t.with_prefix(\"rom\") == [\"romane\", \"romanus\", \"romulus\"] and t.with_prefix(\"x\") == []\nfor _ in range(200):\n    words = {\"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 5))) for _ in range(6)}\n    t = RadixTree()\n    for w in words: t.insert(w)\n    for _ in range(8):\n        q = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 5)))\n        assert t.search(q) == (q in words)\n        assert t.with_prefix(q) == sorted(w for w in words if w.startswith(q)), (words, q)", "more": "- Every internal non-word node has at least two children, so a radix tree on k words has fewer than 2k nodes.\n- Edge splitting is the only tricky step: create a middle node holding the shared part and re-hang the old child under it.\n- Used in routing tables and HTTP routers (longest-prefix match); the same shape as the suffix tree.\n- Compared with a plain trie: less memory and fewer pointer hops, harder to delete from.", "cx": "Insert, search and prefix lookup O(L) for key length L (plus O(output) to list matches). Space O(total key length) worst case, O(k) nodes for k keys.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-ternary-search-tree", "title": "Ternary search tree", "cat": "Strings: structures", "q": ["what is ternary search tree", "explain ternary search tree", "how does ternary search tree work", "ternary search tree in python", "implement ternary search tree", "ternary search tree code", "when to use ternary search tree", "tst data structure", "ternary search tree vs trie"], "tags": "ternary search tree tst trie low equal high autocomplete prefix search memory efficient", "a": "A ternary search tree stores one character per node with three children: lower, equal (move to the next character) and higher. It behaves like a trie but is far smaller than a trie with a 26-slot array per node, and it supports prefix queries and autocomplete.", "code": {"py": "class TNode:\n    __slots__ = (\"ch\", \"lo\", \"eq\", \"hi\", \"end\")\n    def __init__(self, ch):\n        self.ch, self.lo, self.eq, self.hi, self.end = ch, None, None, None, False\n\nclass TST:\n    def __init__(self):\n        self.root = None\n\n    def insert(self, w):\n        if not w:\n            return\n        if self.root is None:\n            self.root = TNode(w[0])\n        node, i = self.root, 0\n        while True:\n            c = w[i]\n            if c < node.ch:\n                node.lo = node.lo or TNode(c); node = node.lo\n            elif c > node.ch:\n                node.hi = node.hi or TNode(c); node = node.hi\n            elif i == len(w) - 1:\n                node.end = True\n                return\n            else:\n                i += 1\n                node.eq = node.eq or TNode(w[i]); node = node.eq\n\n    def _find(self, w):\n        node, i = self.root, 0\n        while node and w:\n            c = w[i]\n            if c < node.ch: node = node.lo\n            elif c > node.ch: node = node.hi\n            elif i == len(w) - 1: return node\n            else: i, node = i + 1, node.eq\n        return None\n\n    def search(self, w):\n        n = self._find(w)\n        return bool(n and n.end)\n\n    def with_prefix(self, pre):\n        n = self._find(pre)\n        if n is None:\n            return []\n        out = [pre] if n.end else []\n        def walk(node, s):\n            if node is None: return\n            walk(node.lo, s)\n            if node.end: out.append(s + node.ch)\n            walk(node.eq, s + node.ch)\n            walk(node.hi, s)\n        walk(n.eq, pre)\n        return out\n\nt = TST()\nfor w in [\"cat\", \"car\", \"cart\", \"dog\"]:\n    t.insert(w)\nprint(t.search(\"car\"), t.with_prefix(\"ca\"))  # True ['car', 'cart', 'cat']"}, "check": "import random\nt = TST()\nfor w in [\"cat\", \"car\", \"cart\", \"dog\"]: t.insert(w)\nassert t.search(\"car\") and not t.search(\"ca\") and not t.search(\"\") and t.with_prefix(\"ca\") == [\"car\", \"cart\", \"cat\"]\nfor _ in range(200):\n    words = {\"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 5))) for _ in range(7)}\n    t = TST()\n    for w in words: t.insert(w)\n    for _ in range(8):\n        q = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 4)))\n        assert t.search(q) == (q in words)\n        assert t.with_prefix(q) == sorted(w for w in words if w.startswith(q)), (words, q)", "more": "- Lo and hi branches work like a binary search tree over the characters at one position; eq advances to the next position.\n- Insertion order affects the shape: sorted input degrades the lo/hi chains (shuffle or balance if needed).\n- Prefix listing is in sorted order thanks to the lo, eq, hi traversal order.\n- Compared with a dict-based trie: similar memory in Python, but the TST is a classic when arrays per node would be wasteful (C, Java).", "cx": "Search and insert O(L + log sigma) on average for key length L and alphabet size sigma; worst case O(L * sigma) on skewed shapes. Space O(total characters).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-levenshtein-automaton", "title": "Levenshtein automaton (fuzzy match within k edits)", "cat": "Strings: matching", "q": ["what is Levenshtein automaton", "explain Levenshtein automaton", "how does Levenshtein automaton work", "Levenshtein automaton in python", "implement Levenshtein automaton", "Levenshtein automaton code", "when to use Levenshtein automaton", "fuzzy string search within k edits", "spell check candidates edit distance 2"], "tags": "levenshtein automaton fuzzy search nfa edit distance k bounded spell check lucene", "a": "A Levenshtein automaton for word w and bound k accepts exactly the strings within edit distance k of w. Simulate its NFA as a set of (position in w, errors used) states while reading the candidate; accept if any state reaches the end of w with at most k errors. Overview with a working simulation, not a compiled DFA.", "code": {"py": "def within_k(word, cand, k):\n    \"\"\"True if edit_distance(word, cand) <= k, by simulating the Levenshtein NFA.\"\"\"\n    def closure(states):                       # deleting word chars costs one error each, no input read\n        out = set(states)\n        stack = list(states)\n        while stack:\n            i, e = stack.pop()\n            if i < len(word) and e < k and (i + 1, e + 1) not in out:\n                out.add((i + 1, e + 1)); stack.append((i + 1, e + 1))\n        return out\n    cur = closure({(0, 0)})\n    for ch in cand:\n        nxt = set()\n        for i, e in cur:\n            if i < len(word) and word[i] == ch:\n                nxt.add((i + 1, e))             # match\n            if e < k:\n                nxt.add((i, e + 1))             # candidate has an extra char (insertion)\n                if i < len(word):\n                    nxt.add((i + 1, e + 1))     # substitution\n        cur = closure(nxt)\n        if not cur:\n            return False\n    return any(i == len(word) for i, e in cur)\n\nprint(within_k(\"kitten\", \"sitten\", 1), within_k(\"kitten\", \"sitting\", 1))  # True False"}, "check": "import random\ndef lev(a, b):\n    prev = list(range(len(b) + 1))\n    for i, x in enumerate(a, 1):\n        cur = [i]\n        for j, y in enumerate(b, 1):\n            cur.append(min(prev[j - 1] + (x != y), prev[j] + 1, cur[j - 1] + 1))\n        prev = cur\n    return prev[-1]\nassert within_k(\"kitten\", \"sitten\", 1) and not within_k(\"kitten\", \"sitting\", 1) and within_k(\"kitten\", \"sitting\", 3)\nfor _ in range(1500):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 6)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 6)))\n    k = random.randint(0, 3)\n    assert within_k(a, b, k) == (lev(a, b) <= k), (a, b, k)", "more": "- The NFA has (len(word)+1) x (k+1) states; each input char advances by match, substitution or insertion, and deletions are epsilon moves in the closure.\n- Production engines compile this to a DFA (the number of states is bounded in terms of k only) and intersect it with a trie or an FST of the dictionary to enumerate all words within k edits without testing each one.\n- Plain alternative for a handful of candidates: banded edit distance.", "cx": "Per candidate: O(len(cand) * len(word) * k) worst case for this set simulation (fewer states in practice). A compiled DFA reads each candidate char in O(1).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-damerau-levenshtein", "title": "Damerau-Levenshtein distance", "cat": "Strings: sequence alignment and compression", "q": ["what is Damerau-Levenshtein distance", "explain Damerau-Levenshtein distance", "how does Damerau-Levenshtein distance work", "Damerau-Levenshtein distance in python", "implement Damerau-Levenshtein distance", "Damerau-Levenshtein distance code", "when to use Damerau-Levenshtein distance", "edit distance with transpositions", "osa vs damerau levenshtein", "levenshtein with swap"], "tags": "damerau levenshtein transposition adjacent swap optimal string alignment osa edit distance", "a": "Damerau-Levenshtein is edit distance with a fourth operation: swapping two adjacent characters costs 1. The simple DP (optimal string alignment, OSA) adds one transposition case but forbids editing a swapped pair again; the true Damerau-Levenshtein DP tracks the last row of each character and satisfies the triangle inequality.", "code": {"py": "def osa(a, b):\n    \"\"\"Optimal string alignment distance (restricted: no substring edited twice).\"\"\"\n    d = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]\n    for i in range(len(a) + 1): d[i][0] = i\n    for j in range(len(b) + 1): d[0][j] = j\n    for i in range(1, len(a) + 1):\n        for j in range(1, len(b) + 1):\n            d[i][j] = min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + (a[i-1] != b[j-1]))\n            if i > 1 and j > 1 and a[i-1] == b[j-2] and a[i-2] == b[j-1]:\n                d[i][j] = min(d[i][j], d[i-2][j-2] + 1)\n    return d[-1][-1]\n\ndef damerau(a, b):\n    \"\"\"True Damerau-Levenshtein distance (unrestricted transpositions).\"\"\"\n    last, inf = {}, len(a) + len(b)\n    d = [[0] * (len(b) + 2) for _ in range(len(a) + 2)]\n    d[0][0] = inf\n    for i in range(len(a) + 1):\n        d[i + 1][0] = inf; d[i + 1][1] = i\n    for j in range(len(b) + 1):\n        d[0][j + 1] = inf; d[1][j + 1] = j\n    for i in range(1, len(a) + 1):\n        db = 0\n        for j in range(1, len(b) + 1):\n            i1, j1 = last.get(b[j - 1], 0), db\n            cost = 0 if a[i - 1] == b[j - 1] else 1\n            if cost == 0: db = j\n            d[i + 1][j + 1] = min(d[i][j] + cost, d[i + 1][j] + 1, d[i][j + 1] + 1,\n                                  d[i1][j1] + (i - i1 - 1) + 1 + (j - j1 - 1))\n        last[a[i - 1]] = i\n    return d[-1][-1]\n\nprint(osa(\"ca\", \"abc\"), damerau(\"ca\", \"abc\"))  # 3 2"}, "check": "import random\nfrom collections import deque\ndef bfs(a, b):\n    alpha = sorted(set(a + b)); cap = max(len(a), len(b)) + 2\n    seen, q = {a: 0}, deque([a])\n    while q:\n        s = q.popleft()\n        if s == b: return seen[s]\n        nb = [s[:i] + s[i + 1:] for i in range(len(s))]\n        nb += [s[:i] + c + s[i:] for i in range(len(s) + 1) for c in alpha] if len(s) < cap else []\n        nb += [s[:i] + c + s[i + 1:] for i in range(len(s)) for c in alpha]\n        nb += [s[:i] + s[i + 1] + s[i] + s[i + 2:] for i in range(len(s) - 1)]\n        for t in nb:\n            if t not in seen: seen[t] = seen[s] + 1; q.append(t)\nassert osa(\"ca\", \"abc\") == 3 and damerau(\"ca\", \"abc\") == 2 and osa(\"ab\", \"ba\") == 1 and damerau(\"\", \"abc\") == 3\nfor _ in range(120):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 4)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 4)))\n    assert damerau(a, b) == bfs(a, b), (a, b)\n    assert damerau(a, b) <= osa(a, b)", "more": "- OSA = Levenshtein DP plus one extra case: if the last two characters are swapped, cost d[i-2][j-2] + 1.\n- OSA can overestimate: \"ca\" to \"abc\" needs 3 in OSA (the swapped pair cannot be edited again) but 2 in the true version (swap, then insert).\n- Spell checkers usually use OSA because swaps are the most common typo; use the true version when you need a real metric.\n- Common mistake: calling OSA \"Damerau-Levenshtein\" and then relying on the triangle inequality.", "cx": "Time O(nm), space O(nm) (OSA can use three rows; the true version needs the full table plus an alphabet map).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-hirschberg", "title": "Hirschberg's algorithm (linear-space LCS/alignment)", "cat": "Strings: sequence alignment and compression", "q": ["what is Hirschberg algorithm", "explain Hirschberg algorithm", "how does Hirschberg algorithm work", "Hirschberg algorithm in python", "implement Hirschberg algorithm", "Hirschberg algorithm code", "when to use Hirschberg algorithm", "lcs in linear space", "reconstruct alignment with O(n) memory"], "tags": "hirschberg linear space lcs alignment divide and conquer forward backward dp rows", "a": "Hirschberg recovers an optimal alignment (here: an LCS string) in O(n) memory. Split the first string in half, compute the LCS-length rows of the left half forward and the right half backward over the second string, pick the split k of the second string maximizing their sum, and recurse on both sides.", "code": {"py": "def lcs_row(a, b):\n    \"\"\"Last DP row: LCS length of a with every prefix b[:j].\"\"\"\n    prev = [0] * (len(b) + 1)\n    for x in a:\n        cur = [0]\n        for j, y in enumerate(b):\n            cur.append(prev[j] + 1 if x == y else max(prev[j + 1], cur[j]))\n        prev = cur\n    return prev\n\ndef hirschberg_lcs(a, b):\n    if not a or not b:\n        return \"\"\n    if len(a) == 1:\n        return a if a in b else \"\"\n    mid = len(a) // 2\n    left = lcs_row(a[:mid], b)\n    right = lcs_row(a[mid:][::-1], b[::-1])\n    k = max(range(len(b) + 1), key=lambda j: left[j] + right[len(b) - j])\n    return hirschberg_lcs(a[:mid], b[:k]) + hirschberg_lcs(a[mid:], b[k:])\n\nprint(hirschberg_lcs(\"AGGTAB\", \"GXTXAYB\"))  # GTAB"}, "check": "import random\ndef lcs_len(a, b): return lcs_row(a, b)[-1]\ndef is_subseq(s, t):\n    it = iter(t); return all(c in it for c in s)\nassert hirschberg_lcs(\"AGGTAB\", \"GXTXAYB\") == \"GTAB\" and hirschberg_lcs(\"\", \"abc\") == \"\"\nfor _ in range(500):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 10)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 10)))\n    r = hirschberg_lcs(a, b)\n    assert len(r) == lcs_len(a, b) and is_subseq(r, a) and is_subseq(r, b), (a, b, r)", "more": "- Every optimal path crosses the middle row of the table at some column k; the forward row gives the best score to reach (mid, k) and the backward row gives the best score from there to the end.\n- The extra recomputation only doubles the total work (a geometric series), so time stays O(nm).\n- Same idea gives linear-space edit-distance alignments and Needleman-Wunsch; use it when the full table does not fit in memory (genome-size strings).\n- For ordinary interview sizes the table + backtrack is simpler.", "cx": "Time O(nm), space O(n + m) (plus recursion depth O(log n)).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-banded-edit-distance", "title": "Banded edit distance (Ukkonen cutoff)", "cat": "Strings: sequence alignment and compression", "q": ["what is banded edit distance", "explain banded edit distance", "how does banded edit distance work", "banded edit distance in python", "implement banded edit distance", "banded edit distance code", "when to use banded edit distance", "edit distance with threshold k", "early exit levenshtein"], "tags": "banded edit distance bounded levenshtein threshold k diagonal band ukkonen cutoff fast", "a": "If you only care whether two strings are within k edits, fill just the diagonal band |i - j| <= k of the DP table: any path leaving the band already costs more than k. The result is exact when it is at most k and \"too far\" otherwise, in O(k * min(n, m)) instead of O(nm).", "code": {"py": "def banded_edit_distance(a, b, k):\n    \"\"\"Edit distance if it is <= k, else None.\"\"\"\n    n, m = len(a), len(b)\n    if abs(n - m) > k:\n        return None\n    big = k + 1\n    prev = {j: j for j in range(min(m, k) + 1)}\n    for i in range(1, n + 1):\n        cur = {}\n        for j in range(max(0, i - k), min(m, i + k) + 1):\n            if j == 0:\n                v = i\n            else:\n                v = min(prev.get(j - 1, big) + (a[i - 1] != b[j - 1]),\n                        prev.get(j, big) + 1,\n                        cur.get(j - 1, big) + 1)\n            cur[j] = min(v, big)\n        prev = cur\n    d = prev.get(m, big)\n    return d if d <= k else None\n\nprint(banded_edit_distance(\"kitten\", \"sitting\", 3), banded_edit_distance(\"kitten\", \"sitting\", 2))  # 3 None"}, "check": "import random\ndef lev(a, b):\n    prev = list(range(len(b) + 1))\n    for i, x in enumerate(a, 1):\n        cur = [i]\n        for j, y in enumerate(b, 1):\n            cur.append(min(prev[j - 1] + (x != y), prev[j] + 1, cur[j - 1] + 1))\n        prev = cur\n    return prev[-1]\nassert banded_edit_distance(\"kitten\", \"sitting\", 3) == 3 and banded_edit_distance(\"kitten\", \"sitting\", 2) is None\nfor _ in range(1500):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    k = random.randint(0, 5)\n    d = lev(a, b)\n    assert banded_edit_distance(a, b, k) == (d if d <= k else None), (a, b, k)", "more": "- A cell (i, j) with |i - j| > k needs more than k insertions or deletions, so it can be treated as infinity.\n- Values are capped at k + 1; anything that reaches the cap means \"more than k\".\n- Doubling trick: when k is unknown, try k = 1, 2, 4, ... until the result is not None (total cost O(d * n)).\n- Fits fuzzy search and diffs of near-identical strings; for random unrelated strings the band covers everything and gains nothing.", "cx": "Time O(k * min(n, m)), space O(k) per row (the dict holds at most 2k + 1 cells).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-needleman-wunsch", "title": "Needleman-Wunsch (global alignment)", "cat": "Strings: sequence alignment and compression", "q": ["what is Needleman-Wunsch", "explain Needleman-Wunsch", "how does Needleman-Wunsch work", "Needleman-Wunsch in python", "implement Needleman-Wunsch", "Needleman-Wunsch code", "when to use Needleman-Wunsch", "global sequence alignment", "dna alignment dynamic programming"], "tags": "needleman wunsch global alignment sequence alignment gap penalty dna scoring matrix traceback", "a": "Needleman-Wunsch aligns two whole sequences with the best total score. DP cell (i, j) is the best score of aligning a[:i] with b[:j]: take the max of diagonal (match or mismatch score), up and left (gap penalty). Trace back from the corner to produce the aligned strings with \"-\" for gaps.", "code": {"py": "def needleman_wunsch(a, b, match=1, mismatch=-1, gap=-2):\n    n, m = len(a), len(b)\n    F = [[0] * (m + 1) for _ in range(n + 1)]\n    for i in range(1, n + 1): F[i][0] = i * gap\n    for j in range(1, m + 1): F[0][j] = j * gap\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            s = match if a[i - 1] == b[j - 1] else mismatch\n            F[i][j] = max(F[i - 1][j - 1] + s, F[i - 1][j] + gap, F[i][j - 1] + gap)\n    x, y, i, j = [], [], n, m\n    while i or j:\n        if i and j and F[i][j] == F[i - 1][j - 1] + (match if a[i - 1] == b[j - 1] else mismatch):\n            x.append(a[i - 1]); y.append(b[j - 1]); i -= 1; j -= 1\n        elif i and F[i][j] == F[i - 1][j] + gap:\n            x.append(a[i - 1]); y.append(\"-\"); i -= 1\n        else:\n            x.append(\"-\"); y.append(b[j - 1]); j -= 1\n    return F[n][m], \"\".join(reversed(x)), \"\".join(reversed(y))\n\nprint(needleman_wunsch(\"GATTACA\", \"GCATGCU\"))"}, "check": "import random\nfrom functools import lru_cache\ndef score_of(x, y, match=1, mismatch=-1, gap=-2):\n    return sum(gap if \"-\" in (p, q) else (match if p == q else mismatch) for p, q in zip(x, y))\ndef brute(a, b):\n    @lru_cache(None)\n    def go(i, j):\n        if i == len(a): return (len(b) - j) * -2\n        if j == len(b): return (len(a) - i) * -2\n        return max(go(i + 1, j + 1) + (1 if a[i] == b[j] else -1), go(i + 1, j) - 2, go(i, j + 1) - 2)\n    return go(0, 0)\nassert needleman_wunsch(\"\", \"ab\")[0] == -4\nfor _ in range(300):\n    a = \"\".join(random.choice(\"ACGT\") for _ in range(random.randint(0, 7)))\n    b = \"\".join(random.choice(\"ACGT\") for _ in range(random.randint(0, 7)))\n    sc, x, y = needleman_wunsch(a, b)\n    assert sc == brute(a, b) and len(x) == len(y) and x.replace(\"-\", \"\") == a and y.replace(\"-\", \"\") == b\n    assert score_of(x, y) == sc and not any(p == q == \"-\" for p, q in zip(x, y))", "more": "- The first row and column are pure gap penalties because aligning a prefix with nothing means all gaps.\n- Several optimal alignments usually exist; the traceback preference order picks one.\n- Linear gap penalty only; affine gaps (open + extend) need three tables (Gotoh).\n- Global alignment forces both ends to align; if only a similar region matters, use Smith-Waterman. Edit distance is the special case match 0, mismatch and gap -1.", "cx": "Time O(nm), space O(nm) for the traceback (O(n + m) with Hirschberg).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-smith-waterman", "title": "Smith-Waterman (local alignment)", "cat": "Strings: sequence alignment and compression", "q": ["what is Smith-Waterman", "explain Smith-Waterman", "how does Smith-Waterman work", "Smith-Waterman in python", "implement Smith-Waterman", "Smith-Waterman code", "when to use Smith-Waterman", "local sequence alignment", "smith waterman vs needleman wunsch"], "tags": "smith waterman local alignment best matching region sequence alignment bioinformatics zero floor", "a": "Smith-Waterman finds the best-scoring matching region of two sequences. It is Needleman-Wunsch with scores floored at 0, so a bad stretch can restart the alignment, and the answer is the highest cell anywhere. Trace back from that cell until the score reaches 0.", "code": {"py": "def smith_waterman(a, b, match=2, mismatch=-1, gap=-1):\n    n, m = len(a), len(b)\n    H = [[0] * (m + 1) for _ in range(n + 1)]\n    best, bi, bj = 0, 0, 0\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            s = match if a[i - 1] == b[j - 1] else mismatch\n            H[i][j] = max(0, H[i - 1][j - 1] + s, H[i - 1][j] + gap, H[i][j - 1] + gap)\n            if H[i][j] > best:\n                best, bi, bj = H[i][j], i, j\n    x, y, i, j = [], [], bi, bj\n    while i and j and H[i][j] > 0:\n        s = match if a[i - 1] == b[j - 1] else mismatch\n        if H[i][j] == H[i - 1][j - 1] + s:\n            x.append(a[i - 1]); y.append(b[j - 1]); i -= 1; j -= 1\n        elif H[i][j] == H[i - 1][j] + gap:\n            x.append(a[i - 1]); y.append(\"-\"); i -= 1\n        else:\n            x.append(\"-\"); y.append(b[j - 1]); j -= 1\n    return best, \"\".join(reversed(x)), \"\".join(reversed(y))\n\nprint(smith_waterman(\"TGTTACGG\", \"GGTTGACTA\"))  # (9, 'GTT-AC', 'GTTGAC')"}, "check": "import random\ndef global_score(x, y, match=2, mismatch=-1, gap=-1):\n    n, m = len(x), len(y)\n    F = [[0] * (m + 1) for _ in range(n + 1)]\n    for i in range(n + 1):\n        for j in range(m + 1):\n            if i == 0 or j == 0: F[i][j] = (i + j) * gap\n            else: F[i][j] = max(F[i-1][j-1] + (match if x[i-1] == y[j-1] else mismatch), F[i-1][j] + gap, F[i][j-1] + gap)\n    return F[n][m]\nassert smith_waterman(\"TGTTACGG\", \"GGTTGACTA\")[0] == 9 and smith_waterman(\"AAA\", \"TTT\")[0] == 0\nfor _ in range(150):\n    a = \"\".join(random.choice(\"ACGT\") for _ in range(random.randint(0, 6)))\n    b = \"\".join(random.choice(\"ACGT\") for _ in range(random.randint(0, 6)))\n    sc, x, y = smith_waterman(a, b)\n    brute = max([0] + [global_score(a[i:j], b[k:l]) for i in range(len(a)) for j in range(i, len(a) + 1)\n                       for k in range(len(b)) for l in range(k, len(b) + 1)])\n    assert sc == brute, (a, b, sc, brute)\n    assert x.replace(\"-\", \"\") in a and y.replace(\"-\", \"\") in b", "more": "- The 0 option means \"start a new alignment here\"; without it negative scores would drag good regions down.\n- Needs a negative expected score for random pairs (mismatch and gap negative), otherwise everything aligns.\n- Local alignment is what BLAST-style tools approximate; the DP itself is exact but quadratic.\n- Affine gaps need the Gotoh three-matrix variant.", "cx": "Time O(nm), space O(nm) with traceback (O(m) if only the score is needed).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-lcs-three", "title": "Longest common subsequence of three strings", "cat": "Strings: sequence alignment and compression", "q": ["what is LCS of three strings", "explain LCS of three strings", "how does LCS of three strings work", "LCS of three strings in python", "implement LCS of three strings", "LCS of three strings code", "when to use LCS of three strings", "lcs of 3 sequences", "common subsequence of multiple strings"], "tags": "lcs three strings 3d dp longest common subsequence of three sequences", "a": "Add a third dimension to the LCS table: cell (i, j, k) is the LCS length of a[:i], b[:j], c[:k]. If the three last characters are equal, take 1 + the diagonal cell; otherwise drop one string and take the best of the three smaller cells.", "code": {"py": "def lcs3(a, b, c):\n    n, m, p = len(a), len(b), len(c)\n    dp = [[[0] * (p + 1) for _ in range(m + 1)] for _ in range(n + 1)]\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            for k in range(1, p + 1):\n                if a[i - 1] == b[j - 1] == c[k - 1]:\n                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1\n                else:\n                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1])\n    return dp[n][m][p]\n\nprint(lcs3(\"abcde\", \"ace\", \"aXcYe\"))  # 3"}, "check": "import random\nfrom itertools import combinations\ndef subseqs(s):\n    return {\"\".join(t) for r in range(len(s) + 1) for t in combinations(s, r)}\nassert lcs3(\"abcde\", \"ace\", \"aXcYe\") == 3 and lcs3(\"\", \"a\", \"a\") == 0\nfor _ in range(300):\n    s = [\"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 6))) for _ in range(3)]\n    common = subseqs(s[0]) & subseqs(s[1]) & subseqs(s[2])\n    assert lcs3(*s) == max(len(t) for t in common)", "more": "- It is enough to consider the drop-one-string cases: if the three last chars are not all equal, at least one of them is not in the LCS tail.\n- Taking the diagonal when all three match is always safe (greedy match is optimal, as in two-string LCS).\n- Generalization to k strings costs O(n^k); the problem is NP-hard when k is part of the input.\n- Reconstruct the string by walking back from dp[n][m][p].", "cx": "Time O(n m p), space O(n m p) (O(m p) with rolling layers if only the length is needed).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-myers-diff", "title": "Myers diff (shortest edit script)", "cat": "Strings: sequence alignment and compression", "q": ["what is Myers diff algorithm", "explain Myers diff algorithm", "how does Myers diff algorithm work", "Myers diff algorithm in python", "implement Myers diff algorithm", "Myers diff algorithm code", "when to use Myers diff algorithm", "how does git diff work", "shortest edit script", "diff two lists of lines"], "tags": "myers diff shortest edit script ses O(ND) git diff insert delete lines edit graph", "a": "Myers' algorithm finds a shortest edit script (insertions and deletions) turning sequence a into b in O((n + m) D) time, where D is the number of edits. It explores the edit graph by diagonals k = x - y, extending the furthest-reaching path for each edit count d, then backtracks the saved frontiers.", "code": {"py": "def myers_diff(a, b):\n    \"\"\"Return a list of ('=', x), ('-', x) or ('+', x) turning a into b with the fewest +/- edits.\"\"\"\n    n, m = len(a), len(b)\n    v, trace = {1: 0}, []\n    for d in range(n + m + 1):\n        trace.append(dict(v))\n        for k in range(-d, d + 1, 2):\n            if k == -d or (k != d and v[k - 1] < v[k + 1]):\n                x = v[k + 1]                # step down: insertion\n            else:\n                x = v[k - 1] + 1            # step right: deletion\n            y = x - k\n            while x < n and y < m and a[x] == b[y]:\n                x += 1; y += 1              # follow the diagonal (free matches)\n            v[k] = x\n            if x >= n and y >= m:\n                return _backtrack(a, b, trace, d)\n    return []\n\ndef _backtrack(a, b, trace, d_end):\n    x, y, ops = len(a), len(b), []\n    for d in range(d_end, -1, -1):\n        v, k = trace[d], x - y\n        if k == -d or (k != d and v[k - 1] < v[k + 1]):\n            pk = k + 1\n        else:\n            pk = k - 1\n        px = v[pk]; py = px - pk\n        while x > px and y > py:\n            ops.append((\"=\", a[x - 1])); x -= 1; y -= 1\n        if d > 0:\n            ops.append((\"+\", b[y - 1]) if x == px else (\"-\", a[x - 1]))\n        x, y = px, py\n    return ops[::-1]\n\nprint(\"\".join(op + str(ch) for op, ch in myers_diff(\"ABCABBA\", \"CBABAC\")))"}, "check": "import random\ndef apply(ops):\n    return [c for op, c in ops if op != \"+\"], [c for op, c in ops if op != \"-\"]\ndef lcs_len(a, b):\n    prev = [0] * (len(b) + 1)\n    for x in a:\n        cur = [0]\n        for j, y in enumerate(b): cur.append(prev[j] + 1 if x == y else max(prev[j + 1], cur[j]))\n        prev = cur\n    return prev[-1]\nassert myers_diff(\"\", \"\") == [] and myers_diff(\"ab\", \"ab\") == [(\"=\", \"a\"), (\"=\", \"b\")]\nfor _ in range(400):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    ops = myers_diff(a, b)\n    src, dst = apply(ops)\n    assert \"\".join(src) == a and \"\".join(dst) == b, (a, b, ops)\n    edits = sum(op != \"=\" for op, _ in ops)\n    assert edits == len(a) + len(b) - 2 * lcs_len(a, b), (a, b, ops)", "more": "- D equals n + m - 2 * LCS: diffing is LCS in disguise, with only inserts and deletes.\n- v[k] is the furthest x reached on diagonal k after d edits; the greedy \"furthest\" choice is safe because a farther point dominates.\n- Output quality: many shortest scripts exist; real tools add heuristics (patience diff, histogram) for more readable results.\n- Use the quadratic LCS table for tiny inputs; use Myers when the files are mostly equal.", "cx": "Time O((n + m) D) expected, worst case O((n + m)^2). This version stores a copy of the frontier per round, so space is O(D^2) (the linear-space refinement divides and conquers).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-lcs-reconstruct", "title": "Longest common subsequence reconstruction (backtrack)", "cat": "Strings: sequence alignment and compression", "q": ["what is LCS reconstruction", "explain LCS reconstruction", "how does LCS reconstruction work", "LCS reconstruction in python", "implement LCS reconstruction", "LCS reconstruction code", "when to use LCS reconstruction", "print the longest common subsequence", "lcs string not just length"], "tags": "lcs reconstruct print the subsequence backtrack dp table longest common subsequence string", "a": "Fill the LCS length table, then walk back from the bottom-right corner: if the two characters are equal, take it and go diagonal; otherwise move to the neighbour with the larger value (up if equal). Reverse the collected characters. Length alone needs only the table; the string needs the backtrack.", "code": {"py": "def lcs(a, b):\n    n, m = len(a), len(b)\n    dp = [[0] * (m + 1) for _ in range(n + 1)]\n    for i in range(n):\n        for j in range(m):\n            dp[i + 1][j + 1] = dp[i][j] + 1 if a[i] == b[j] else max(dp[i][j + 1], dp[i + 1][j])\n    out, i, j = [], n, m\n    while i and j:\n        if a[i - 1] == b[j - 1]:\n            out.append(a[i - 1]); i -= 1; j -= 1\n        elif dp[i - 1][j] >= dp[i][j - 1]:\n            i -= 1\n        else:\n            j -= 1\n    return \"\".join(reversed(out))\n\nprint(lcs(\"AGGTAB\", \"GXTXAYB\"))  # GTAB"}, "check": "import random\nfrom itertools import combinations\ndef subseqs(s): return {\"\".join(t) for r in range(len(s) + 1) for t in combinations(s, r)}\nassert lcs(\"AGGTAB\", \"GXTXAYB\") == \"GTAB\" and lcs(\"\", \"x\") == \"\" and lcs(\"abc\", \"abc\") == \"abc\"\nfor _ in range(300):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 7)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 7)))\n    r = lcs(a, b)\n    assert r in subseqs(a) and r in subseqs(b)\n    assert len(r) == max(len(t) for t in subseqs(a) & subseqs(b))", "more": "- The table must keep all rows for the backtrack (rolling rows only give the length); use Hirschberg for linear space.\n- Ties between up and left give different but equally long answers.\n- Subsequence is not substring: gaps are allowed (contrast with longest common substring).\n- Counting all distinct LCS strings needs an extra DP over the same table.", "cx": "Time O(nm), space O(nm).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-wildcard-matching", "title": "Wildcard and glob matching (? and *)", "cat": "Strings: sequence alignment and compression", "q": ["what is wildcard matching", "explain wildcard matching", "how does wildcard matching work", "wildcard matching in python", "implement wildcard matching", "wildcard matching code", "when to use wildcard matching", "glob matching", "leetcode wildcard matching", "fnmatch algorithm"], "tags": "wildcard matching glob pattern star question mark dp greedy two pointer leetcode 44 fnmatch", "a": "Match a string against a pattern where \"?\" matches any one char and \"*\" matches any run (including empty). DP: dp[i][j] says whether s[:i] matches p[:j]; a star can match nothing (dp[i][j-1]) or one more char (dp[i-1][j]). A two-pointer version with backtracking to the last star needs only O(1) space.", "code": {"py": "def wildcard_match(s, p):\n    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]\n    dp[0][0] = True\n    for j in range(1, len(p) + 1):\n        dp[0][j] = dp[0][j - 1] and p[j - 1] == \"*\"\n    for i in range(1, len(s) + 1):\n        for j in range(1, len(p) + 1):\n            if p[j - 1] == \"*\":\n                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]\n            else:\n                dp[i][j] = dp[i - 1][j - 1] and p[j - 1] in (\"?\", s[i - 1])\n    return dp[-1][-1]\n\ndef glob_greedy(s, p):\n    i = j = 0\n    star = match = -1\n    while i < len(s):\n        if j < len(p) and p[j] in (\"?\", s[i]):\n            i += 1; j += 1\n        elif j < len(p) and p[j] == \"*\":\n            star, match = j, i; j += 1          # try matching zero chars first\n        elif star != -1:\n            j = star + 1; match += 1; i = match  # let the last star swallow one more char\n        else:\n            return False\n    while j < len(p) and p[j] == \"*\":\n        j += 1\n    return j == len(p)\n\nprint(wildcard_match(\"adceb\", \"*a*b\"), glob_greedy(\"acdcb\", \"a*c?b\"))  # True False"}, "check": "import random\nfrom fnmatch import fnmatchcase\nassert wildcard_match(\"adceb\", \"*a*b\") and not glob_greedy(\"acdcb\", \"a*c?b\") and wildcard_match(\"\", \"***\")\nfor _ in range(2000):\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 7)))\n    p = \"\".join(random.choice(\"ab?*\") for _ in range(random.randint(0, 6)))\n    exp = fnmatchcase(s, p)\n    assert wildcard_match(s, p) == exp == glob_greedy(s, p), (s, p)", "more": "- Collapse consecutive stars first to avoid redundant work.\n- The greedy version only ever needs the most recent star: matching it shorter can never hurt earlier stars (so no deeper backtracking).\n- Do not confuse with regex: here \"*\" is a wildcard by itself, in regex it modifies the previous token.\n- Python's `fnmatch` and `glob` already do this (plus [seq] sets).", "cx": "DP: O(nm) time and space (O(m) with one row). Greedy: O(nm) worst case, O(1) space, usually near-linear.", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-regex-dp", "title": "Regular expression matching with . and * (DP)", "cat": "Strings: sequence alignment and compression", "q": ["what is regex matching dp", "explain regex matching dp", "how does regex matching dp work", "regex matching dp in python", "implement regex matching dp", "regex matching dp code", "when to use regex matching dp", "regular expression matching leetcode 10", "implement regex with dot and star"], "tags": "regular expression matching dp dot star leetcode 10 pattern match recursion memo", "a": "For patterns with \".\" (any char) and \"x*\" (zero or more of x), let dp[i][j] mean s[:i] matches p[:j]. A star token either matches zero copies (dp[i][j-2]) or consumes one more matching char (dp[i-1][j] when the char before the star fits s[i-1]). Everything else is a direct character match.", "code": {"py": "def is_match(s, p):\n    n, m = len(s), len(p)\n    dp = [[False] * (m + 1) for _ in range(n + 1)]\n    dp[0][0] = True\n    for j in range(2, m + 1):\n        dp[0][j] = p[j - 1] == \"*\" and dp[0][j - 2]\n    for i in range(1, n + 1):\n        for j in range(1, m + 1):\n            if p[j - 1] == \"*\":\n                dp[i][j] = dp[i][j - 2] or (p[j - 2] in (\".\", s[i - 1]) and dp[i - 1][j])\n            else:\n                dp[i][j] = p[j - 1] in (\".\", s[i - 1]) and dp[i - 1][j - 1]\n    return dp[n][m]\n\nprint(is_match(\"aab\", \"c*a*b\"), is_match(\"mississippi\", \"mis*is*p*.\"))  # True False"}, "check": "import random, re\nassert is_match(\"aab\", \"c*a*b\") and not is_match(\"mississippi\", \"mis*is*p*.\") and is_match(\"\", \"a*\")\nfor _ in range(3000):\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 7)))\n    p = \"\".join(random.choice(\"ab.\") + random.choice([\"\", \"\", \"*\"]) for _ in range(random.randint(0, 4)))\n    assert is_match(s, p) == bool(re.fullmatch(p, s)), (s, p)", "more": "- The pattern is assumed valid: \"*\" never starts it and never follows another \"*\".\n- The star case is the whole problem: \"zero copies\" looks two tokens back, \"one more\" stays in the same pattern column.\n- Top-down memoized recursion is equivalent and often easier to write correctly in an interview.\n- For full regex syntax (alternation, groups) use the NFA simulation in the Thompson entry instead.", "cx": "Time O(nm), space O(nm) (O(m) with rolling rows).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-thompson-nfa", "title": "Thompson NFA regex engine (small)", "cat": "Strings: matching", "q": ["what is Thompson NFA regex", "explain Thompson NFA regex", "how does Thompson NFA regex work", "Thompson NFA regex in python", "implement Thompson NFA regex", "Thompson NFA regex code", "when to use Thompson NFA regex", "regex without backtracking", "build a regex engine", "nfa simulation for regular expressions"], "tags": "thompson nfa regex engine regular expression linear time no backtracking alternation star plus optional parentheses", "a": "Thompson's construction turns a regex into an NFA, and matching simulates all active states at once, one input char at a time, so there is no backtracking blowup. This small engine supports literals, \".\", \"|\", \"*\", \"+\", \"?\" and parentheses, and matches the whole string.", "code": {"py": "def parse(p):\n    pos = 0\n    def alt():\n        nonlocal pos\n        parts = [cat()]\n        while pos < len(p) and p[pos] == \"|\":\n            pos += 1; parts.append(cat())\n        return parts[0] if len(parts) == 1 else (\"alt\", parts)\n    def cat():\n        nonlocal pos\n        items = []\n        while pos < len(p) and p[pos] not in \"|)\":\n            items.append(rep())\n        return (\"cat\", items)\n    def rep():\n        nonlocal pos\n        if p[pos] == \"(\":\n            pos += 1; node = alt(); assert p[pos] == \")\"; pos += 1\n        else:\n            node = (\"any\",) if p[pos] == \".\" else (\"chr\", p[pos]); pos += 1\n        if pos < len(p) and p[pos] in \"*+?\":\n            node = ({\"*\": \"star\", \"+\": \"plus\", \"?\": \"opt\"}[p[pos]], node); pos += 1\n        return node\n    return alt()\n\nclass NFA:\n    def __init__(self, pattern):\n        self.st = []                                   # [kind, char, out1, out2]\n        self.match = self._new(\"match\")\n        self.start = self._build(parse(pattern), self.match)\n    def _new(self, kind, ch=None, o1=None, o2=None):\n        self.st.append([kind, ch, o1, o2]); return len(self.st) - 1\n    def _build(self, node, nxt):                      # compile backwards: node must continue at nxt\n        t = node[0]\n        if t == \"chr\": return self._new(\"chr\", node[1], nxt)\n        if t == \"any\": return self._new(\"any\", None, nxt)\n        if t == \"cat\":\n            for part in reversed(node[1]): nxt = self._build(part, nxt)\n            return nxt\n        if t == \"alt\":\n            starts = [self._build(x, nxt) for x in node[1]]\n            s = starts[-1]\n            for o in reversed(starts[:-1]): s = self._new(\"split\", None, o, s)\n            return s\n        if t == \"opt\": return self._new(\"split\", None, self._build(node[1], nxt), nxt)\n        s = self._new(\"split\", None, None, nxt)       # star / plus share a loop state\n        body = self._build(node[1], s)\n        self.st[s][2] = body\n        return s if t == \"star\" else body\n    def _add(self, s, out):\n        stack = [s]\n        while stack:\n            i = stack.pop()\n            if i in out: continue\n            out.add(i)\n            if self.st[i][0] == \"split\": stack += [self.st[i][2], self.st[i][3]]\n    def fullmatch(self, text):\n        cur = set(); self._add(self.start, cur)\n        for ch in text:\n            nxt = set()\n            for i in cur:\n                k, c, o1, _ = self.st[i]\n                if k == \"any\" or (k == \"chr\" and c == ch): self._add(o1, nxt)\n            cur = nxt\n        return self.match in cur\n\nprint(NFA(\"(a|b)*abb\").fullmatch(\"babb\"), NFA(\"a+b?\").fullmatch(\"aaa\"))  # True True"}, "check": "import random, re\nassert NFA(\"(a|b)*abb\").fullmatch(\"babb\") and not NFA(\"a+b?\").fullmatch(\"\") and NFA(\"\").fullmatch(\"\")\ndef gen(depth=0):\n    r = random.random()\n    if depth > 2 or r < .45: base = random.choice(\"ab.\")\n    elif r < .7: base = \"(\" + gen(depth + 1) + \"|\" + gen(depth + 1) + \")\"\n    else: base = \"(\" + gen(depth + 1) + gen(depth + 1) + \")\"\n    return base + (random.choice([\"\", \"\", \"*\", \"+\", \"?\"]) if depth == 0 else \"\")   # no nested quantifiers: Python re can backtrack exponentially\nfor _ in range(1500):\n    p = gen() + gen()\n    s = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 6)))\n    assert NFA(p).fullmatch(s) == bool(re.fullmatch(p, s)), (p, s)", "more": "- The NFA state set holds every place the matcher could be; each char moves all of them, so work is bounded by states x length.\n- Epsilon closure (the `_add` walk over split states) is what makes \"(a*)*\" safe: a visited set stops infinite loops.\n- Backtracking engines (Python `re`) are faster in common cases but can take exponential time on patterns like (a+)+$; this simulation cannot.\n- Missing here: classes [a-z], anchors, counted repeats, captures.", "cx": "Compile O(m) states for pattern length m; match O(n * m) time, O(m) space.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-sellers", "title": "Approximate string matching (Sellers)", "cat": "Strings: matching", "q": ["what is approximate string matching Sellers", "explain approximate string matching Sellers", "how does approximate string matching Sellers work", "approximate string matching Sellers in python", "implement approximate string matching Sellers", "approximate string matching Sellers code", "when to use approximate string matching Sellers", "fuzzy substring search", "find pattern in text with k mistakes", "approximate pattern matching dp"], "tags": "sellers algorithm approximate matching fuzzy substring k differences edit distance text free start row", "a": "Sellers' algorithm finds where a pattern occurs in a text with at most k edits. It is the edit-distance DP with one change: the top row is all zeros, so a match may start anywhere in the text. Any text position j whose last-row cell is at most k ends an approximate occurrence.", "code": {"py": "def sellers(pattern, text, k):\n    \"\"\"Return [(end_index, edits)] for every text position where pattern ends with <= k edits.\"\"\"\n    m = len(pattern)\n    prev = list(range(m + 1))              # column before the text starts\n    out = []\n    for j, c in enumerate(text):\n        cur = [0]                          # free start: empty pattern prefix costs 0\n        for i in range(1, m + 1):\n            cur.append(min(prev[i - 1] + (pattern[i - 1] != c), prev[i] + 1, cur[i - 1] + 1))\n        if cur[m] <= k:\n            out.append((j, cur[m]))\n        prev = cur\n    return out\n\nprint(sellers(\"abc\", \"xabdcx\", 1))  # [(2, 1), (3, 1), (4, 1)]"}, "check": "import random\ndef lev(a, b):\n    prev = list(range(len(b) + 1))\n    for i, x in enumerate(a, 1):\n        cur = [i]\n        for j, y in enumerate(b, 1):\n            cur.append(min(prev[j - 1] + (x != y), prev[j] + 1, cur[j - 1] + 1))\n        prev = cur\n    return prev[-1]\nassert sellers(\"abc\", \"xabdcx\", 1) == [(2, 1), (3, 1), (4, 1)] and sellers(\"a\", \"\", 1) == []\nfor _ in range(400):\n    p = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 4)))\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 8)))\n    k = random.randint(0, 2)\n    exp = []\n    for j in range(len(t)):\n        d = min(lev(p, t[s:j + 1]) for s in range(j + 2))\n        if d <= k: exp.append((j, d))\n    assert sellers(p, t, k) == exp, (p, t, k)", "more": "- Only the first row differs from edit distance: D[0][j] = 0 for all j, instead of j.\n- The value in the last row is the best distance of the pattern to any text substring ending at that position.\n- Recovering the start needs a traceback or a second pass on the reversed strings.\n- Faster for small k: Landau-Vishkin / bit-parallel Myers; for k = 0 it is plain substring search.", "cx": "Time O(nm), space O(m) with one column.", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-shift-and", "title": "Shift-And (bitap) matching", "cat": "Strings: matching", "q": ["what is Shift-And bitap", "explain Shift-And bitap", "how does Shift-And bitap work", "Shift-And bitap in python", "implement Shift-And bitap", "Shift-And bitap code", "when to use Shift-And bitap", "bitap algorithm", "bit parallel pattern matching"], "tags": "shift and bitap bit parallel string matching bitmask pattern state word", "a": "Shift-And keeps a bitmask D where bit i says \"the first i+1 pattern chars match the text ending here\". For each text char: D = ((D << 1) | 1) & mask[char], where mask[c] has bit i set when pattern[i] == c. A match ends whenever the top bit is set. Great for short patterns that fit in a machine word.", "code": {"py": "def shift_and(text, pat):\n    m = len(pat)\n    if m == 0:\n        return list(range(len(text) + 1))\n    mask = {}\n    for i, c in enumerate(pat):\n        mask[c] = mask.get(c, 0) | (1 << i)\n    d, res = 0, []\n    for i, c in enumerate(text):\n        d = ((d << 1) | 1) & mask.get(c, 0)\n        if d >> (m - 1) & 1:\n            res.append(i - m + 1)\n    return res\n\nprint(shift_and(\"abracadabra\", \"abra\"))  # [0, 7]"}, "check": "import random\nassert shift_and(\"abracadabra\", \"abra\") == [0, 7] and shift_and(\"\", \"a\") == []\nfor _ in range(500):\n    t = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 14)))\n    p = \"\".join(random.choice(\"ab\") for _ in range(random.randint(1, 5)))\n    assert shift_and(t, p) == [i for i in range(len(t) - len(p) + 1) if t.startswith(p, i)], (t, p)", "more": "- The `| 1` starts a new match attempt at every text position; the `& mask` kills attempts whose next char is wrong.\n- All m alignments are checked in parallel in one word operation, so it is O(n) when m <= word size (64); Python ints are unbounded, but then each step costs O(m / 64).\n- Extending it to k mismatches or k edits (Wu-Manber) keeps one bitmask per error count.\n- Character classes in the pattern just set several mask bits.", "cx": "Time O(n * ceil(m / w)) for word size w, space O(alphabet) masks.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-anagram-window", "title": "Find all anagrams in a string (sliding window counts)", "cat": "Strings: matching", "q": ["what is anagram search sliding window", "explain anagram search sliding window", "how does anagram search sliding window work", "anagram search sliding window in python", "implement anagram search sliding window", "anagram search sliding window code", "when to use anagram search sliding window", "permutation in string", "sliding window character count", "find all anagrams of p in s"], "tags": "anagram search find all anagrams sliding window character counts permutation in string", "a": "To find every substring of s that is an anagram of p, slide a window of length len(p) and keep character counts. Track how many needed letters currently have exactly the right count; when that equals the number of distinct letters in p, the window is an anagram. Each step changes just two counts.", "code": {"py": "from collections import Counter\n\ndef find_anagrams(s, p):\n    m, need, have, res = len(p), Counter(p), Counter(), []\n    formed = 0                                   # letters of p whose window count equals the needed count\n    def bump(ch, delta):\n        nonlocal formed\n        if ch not in need:\n            return\n        formed -= have[ch] == need[ch]\n        have[ch] += delta\n        formed += have[ch] == need[ch]\n    for i, ch in enumerate(s):\n        bump(ch, 1)\n        if i >= m:\n            bump(s[i - m], -1)\n        if i >= m - 1 and formed == len(need):\n            res.append(i - m + 1)\n    return res\n\nprint(find_anagrams(\"cbaebabacd\", \"abc\"))  # [0, 6]"}, "check": "import random\nassert find_anagrams(\"cbaebabacd\", \"abc\") == [0, 6] and find_anagrams(\"ab\", \"abc\") == []\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 12)))\n    p = \"\".join(random.choice(\"abc\") for _ in range(random.randint(1, 4)))\n    exp = [i for i in range(len(s) - len(p) + 1) if sorted(s[i:i + len(p)]) == sorted(p)]\n    assert find_anagrams(s, p) == exp, (s, p)", "more": "- Window length equals len(p) so equal counts for every needed letter means the window is a permutation of p.\n- Comparing two Counters each step also works but costs O(alphabet) per step; the `formed` counter makes each step O(1).\n- Order matters in `bump`: unmark the old state, change the count, mark the new state.\n- Variants: permutation in string (just need the first hit), group anagrams (sort letters as a key).", "cx": "Time O(n + m), space O(alphabet).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-double-hash", "title": "String hashing with a double modulus", "cat": "Strings: matching", "q": ["what is polynomial string hashing", "explain polynomial string hashing", "how does polynomial string hashing work", "polynomial string hashing in python", "implement polynomial string hashing", "polynomial string hashing code", "when to use polynomial string hashing", "rolling hash substring comparison", "hash a substring in o(1)", "polynomial hash collision"], "tags": "string hashing polynomial hash double modulus prefix hash substring compare collision rolling", "a": "Polynomial hashing maps a string to sum(s[i] * B^(len-1-i)) mod M. With prefix hashes, the hash of any substring is computed in O(1), so two substrings can be compared fast. Using two independent (base, modulus) pairs makes accidental collisions very unlikely.", "code": {"py": "import random\n\nclass StringHash:\n    def __init__(self, s, mods=(1_000_000_007, 998_244_353)):\n        self.mods = mods\n        self.bases = [random.randrange(300, m - 1) for m in mods]    # random bases defeat anti-hash tests\n        n = len(s)\n        self.h = [[0] * (n + 1) for _ in mods]\n        self.p = [[1] * (n + 1) for _ in mods]\n        for k, (m, b) in enumerate(zip(mods, self.bases)):\n            for i, c in enumerate(s):\n                self.h[k][i + 1] = (self.h[k][i] * b + ord(c)) % m\n                self.p[k][i + 1] = self.p[k][i] * b % m\n\n    def get(self, l, r):\n        \"\"\"Hash of s[l:r].\"\"\"\n        return tuple((self.h[k][r] - self.h[k][l] * self.p[k][r - l]) % m for k, m in enumerate(self.mods))\n\ns = \"abracadabra\"\nH = StringHash(s)\nprint(H.get(0, 4) == H.get(7, 11), H.get(0, 3) == H.get(1, 4))  # True False"}, "check": "import random\ns = \"abracadabra\"\nH = StringHash(s)\nassert H.get(0, 4) == H.get(7, 11) and H.get(0, 3) != H.get(1, 4) and H.get(2, 2) == (0, 0)\nfor _ in range(20):\n    t = \"\".join(random.choice(\"ab\") for _ in range(30))\n    H = StringHash(t)\n    for _ in range(100):\n        l1, l2 = random.randint(0, 25), random.randint(0, 25)\n        L = random.randint(0, 5)\n        assert (H.get(l1, l1 + L) == H.get(l2, l2 + L)) == (t[l1:l1 + L] == t[l2:l2 + L])", "more": "- Subtracting h[l] * B^(r-l) cancels the prefix contribution; keep the result non-negative with the final `% m`.\n- One 32-bit modulus has about a 1-in-10^9 collision chance per pair, which is far too high with millions of comparisons (birthday paradox); two moduli, or one 61-bit modulus (2^61 - 1), fix that.\n- Use `ord(c)` (never 0) so that \"a\" and \"aa\" cannot collide trivially.\n- A hash match is only a strong hint; verify directly when a wrong answer is costly.", "cx": "Build O(n), each substring hash O(1), space O(n) per modulus.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-longest-duplicate-substring", "title": "Longest duplicate substring (binary search + rolling hash)", "cat": "Strings: matching", "q": ["what is longest duplicate substring", "explain longest duplicate substring", "how does longest duplicate substring work", "longest duplicate substring in python", "implement longest duplicate substring", "longest duplicate substring code", "when to use longest duplicate substring", "leetcode 1044", "longest repeated substring rolling hash"], "tags": "longest duplicate substring binary search rolling hash leetcode 1044 repeated substring", "a": "Duplicate-ness is monotone: if some substring of length L occurs twice, so does one of length L-1. Binary search on L; for each L slide a rolling hash across the string and look for a repeated hash, confirming with a direct comparison. The largest L that works gives the answer.", "code": {"py": "import random\n\ndef longest_dup_substring(s):\n    n, M = len(s), (1 << 61) - 1\n    B = random.randrange(1 << 20, M - 1)\n\n    def find_dup(L):\n        \"\"\"Start index of a second occurrence of some length-L substring, or -1.\"\"\"\n        h = 0\n        for c in s[:L]:\n            h = (h * B + ord(c)) % M\n        seen = {h: [0]}\n        top = pow(B, L, M)\n        for i in range(1, n - L + 1):\n            h = (h * B + ord(s[i + L - 1]) - ord(s[i - 1]) * top) % M\n            for j in seen.get(h, ()):\n                if s[j:j + L] == s[i:i + L]:\n                    return i\n            seen.setdefault(h, []).append(i)\n        return -1\n\n    lo, hi, best = 1, n - 1, \"\"\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        i = find_dup(mid)\n        if i != -1:\n            best, lo = s[i:i + mid], mid + 1\n        else:\n            hi = mid - 1\n    return best\n\nprint(longest_dup_substring(\"banana\"))  # ana"}, "check": "import random\nassert longest_dup_substring(\"banana\") == \"ana\" and longest_dup_substring(\"abcd\") == \"\" and longest_dup_substring(\"a\") == \"\"\nfor _ in range(300):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 16)))\n    brute = max([L for L in range(1, len(s)) if any(s.find(s[i:i + L], i + 1) != -1 for i in range(len(s) - L + 1))] + [0])\n    r = longest_dup_substring(s)\n    assert len(r) == brute and (brute == 0 or s.count(r) >= 2 or s.find(r, s.find(r) + 1) != -1), (s, r)", "more": "- Monotonicity is what allows binary search: a duplicate of length L contains a duplicate of every shorter length.\n- Checking the actual substrings after a hash hit keeps the answer exact even if two different substrings collide.\n- Occurrences may overlap (\"ana\" in \"banana\").\n- Deterministic alternative: suffix array + LCP (maximum LCP), O(n log n) or better.", "cx": "Expected O(n log n) time (log n rounds of an O(n) scan plus verification), space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-huffman", "title": "Huffman coding (build, encode, decode, canonical codes)", "cat": "Strings: sequence alignment and compression", "q": ["what is Huffman coding", "explain Huffman coding", "how does Huffman coding work", "Huffman coding in python", "implement Huffman coding", "Huffman coding code", "when to use Huffman coding", "huffman tree", "prefix code compression", "canonical huffman codes"], "tags": "huffman coding prefix code optimal compression priority queue encode decode canonical huffman code lengths", "a": "Huffman coding builds an optimal prefix-free binary code: repeatedly merge the two lowest-frequency nodes into one parent (min-heap), then read codes off the tree (left 0, right 1). Frequent symbols get short codes. Canonical Huffman keeps only the code lengths and assigns codes in sorted order, so the decoder can rebuild them.", "code": {"py": "import heapq\nfrom collections import Counter\nfrom itertools import count\n\ndef huffman_codes(text):\n    freq = Counter(text)\n    if not freq:\n        return {}\n    if len(freq) == 1:\n        return {next(iter(freq)): \"0\"}\n    tie = count()                                     # tie-break so tuples never compare nodes\n    heap = [(f, next(tie), ch) for ch, f in freq.items()]\n    heapq.heapify(heap)\n    while len(heap) > 1:\n        f1, _, a = heapq.heappop(heap)\n        f2, _, b = heapq.heappop(heap)\n        heapq.heappush(heap, (f1 + f2, next(tie), (a, b)))\n    codes = {}\n    def walk(node, prefix):\n        if isinstance(node, tuple):\n            walk(node[0], prefix + \"0\"); walk(node[1], prefix + \"1\")\n        else:\n            codes[node] = prefix\n    walk(heap[0][2], \"\")\n    return codes\n\ndef huffman_encode(text, codes):\n    return \"\".join(codes[c] for c in text)\n\ndef huffman_decode(bits, codes):\n    inv, out, cur = {v: k for k, v in codes.items()}, [], \"\"\n    for b in bits:\n        cur += b\n        if cur in inv:\n            out.append(inv[cur]); cur = \"\"\n    return \"\".join(out)\n\ndef canonical_codes(lengths):\n    \"\"\"lengths: {symbol: code length}. Same lengths, but codes assigned in (length, symbol) order.\"\"\"\n    codes, code, prev = {}, 0, 0\n    for sym, ln in sorted(lengths.items(), key=lambda kv: (kv[1], kv[0])):\n        code <<= ln - prev\n        codes[sym] = format(code, \"0%db\" % ln)\n        code, prev = code + 1, ln\n    return codes\n\ntext = \"abracadabra\"\ncodes = huffman_codes(text)\nbits = huffman_encode(text, codes)\nprint(len(bits), huffman_decode(bits, codes) == text)  # 23 True"}, "check": "import heapq, random\nfor _ in range(300):\n    t = \"\".join(random.choice(\"abcdef\"[:random.randint(1, 6)]) for _ in range(random.randint(0, 25)))\n    codes = huffman_codes(t)\n    bits = huffman_encode(t, codes)\n    assert huffman_decode(bits, codes) == t\n    vals = list(codes.values())\n    assert not any(x != y and y.startswith(x) for x in vals for y in vals)       # prefix-free\n    freq = {c: t.count(c) for c in set(t)}\n    if len(freq) > 1:                                                           # cost = sum of merged weights\n        h = list(freq.values()); heapq.heapify(h); cost = 0\n        while len(h) > 1:\n            x, y = heapq.heappop(h), heapq.heappop(h); cost += x + y; heapq.heappush(h, x + y)\n        assert len(bits) == cost\n    canon = canonical_codes({c: len(v) for c, v in codes.items()})\n    assert {c: len(v) for c, v in canon.items()} == {c: len(v) for c, v in codes.items()}\n    cv = list(canon.values())\n    assert not any(x != y and y.startswith(x) for x in cv for y in cv)\nassert canonical_codes({\"a\": 1, \"b\": 2, \"c\": 3, \"d\": 3}) == {\"a\": \"0\", \"b\": \"10\", \"c\": \"110\", \"d\": \"111\"}", "more": "- Greedy choice: the two rarest symbols can be siblings at the deepest level of some optimal tree, so merging them first is safe.\n- Total encoded length equals the sum of all merged weights, a handy test.\n- A single distinct symbol needs a special case (give it one bit).\n- The decoder needs the code table or the frequencies; canonical codes shrink that to just the lengths (used by DEFLATE).\n- Huffman is optimal among whole-bit-per-symbol codes; arithmetic coding can beat it by using fractional bits.", "cx": "Build O(k log k) for k distinct symbols; encoding O(n); decoding O(total bits). Space O(k).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-arithmetic-coding", "title": "Arithmetic coding (overview with exact toy)", "cat": "Strings: sequence alignment and compression", "q": ["what is arithmetic coding", "explain arithmetic coding", "how does arithmetic coding work", "arithmetic coding in python", "implement arithmetic coding", "arithmetic coding code", "when to use arithmetic coding", "arithmetic coding vs huffman", "how does a range coder work"], "tags": "arithmetic coding entropy coding interval subdivision fractions range coder compression probability model", "a": "Arithmetic coding represents an entire message as one number in [0, 1). Start with the interval [0, 1) and, for each symbol, shrink it to that symbol's sub-interval proportional to its probability. Any number inside the final interval identifies the message. This overview uses exact fractions; real coders use integer arithmetic with renormalization.", "code": {"py": "from fractions import Fraction\n\ndef _ranges(probs):\n    cum, c = {}, Fraction(0)\n    for s, p in probs.items():\n        cum[s] = (c, c + p); c += p\n    assert c == 1\n    return cum\n\ndef ac_encode(msg, probs):\n    cum, lo, hi = _ranges(probs), Fraction(0), Fraction(1)\n    for s in msg:\n        a, b = cum[s]\n        w = hi - lo\n        lo, hi = lo + w * a, lo + w * b\n    return (lo + hi) / 2                      # any value in [lo, hi) works\n\ndef ac_decode(x, n, probs):\n    cum, out = _ranges(probs), []\n    for _ in range(n):\n        for s, (a, b) in cum.items():\n            if a <= x < b:\n                out.append(s); x = (x - a) / (b - a); break\n    return \"\".join(out)\n\nP = {\"a\": Fraction(1, 2), \"b\": Fraction(1, 4), \"c\": Fraction(1, 4)}\nx = ac_encode(\"abac\", P)\nprint(x, ac_decode(x, 4, P))  # 39/128 abac"}, "check": "import random\nfrom fractions import Fraction\nP = {\"a\": Fraction(1, 2), \"b\": Fraction(1, 4), \"c\": Fraction(1, 4)}\nassert ac_decode(ac_encode(\"abac\", P), 4, P) == \"abac\" and ac_decode(ac_encode(\"\", P), 0, P) == \"\"\nfor _ in range(300):\n    m = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 12)))\n    assert ac_decode(ac_encode(m, P), len(m), P) == m", "more": "- The final interval width is the product of the symbol probabilities, so about -log2(width) bits are needed: close to the entropy, with no whole-bit rounding per symbol.\n- The decoder must know the message length (or an end symbol) and the same model.\n- Real implementations (range coders) keep a finite-precision integer interval and emit bits as the top bits settle; this toy needs unbounded precision.\n- Adaptive models update the probabilities after each symbol (used in modern codecs).", "cx": "Exact-fraction toy: O(n) steps but numbers grow to O(n) bits (so O(n^2) bit operations). Practical coders: O(n) time with fixed-width integers.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-lz77", "title": "LZ77 compression", "cat": "Strings: sequence alignment and compression", "q": ["what is LZ77", "explain LZ77", "how does LZ77 work", "LZ77 in python", "implement LZ77", "LZ77 code", "when to use LZ77", "sliding window compression", "lz77 vs lz78", "deflate algorithm basics"], "tags": "lz77 sliding window compression back reference offset length literal deflate gzip", "a": "LZ77 compresses by replacing repeated text with back-references. At each position find the longest match inside a sliding window of recent output and emit (offset, length, next character). The decoder copies from its own output, and the match may overlap the current position, which gives run-length-like behaviour.", "code": {"py": "def lz77_encode(s, window=255):\n    out, i = [], 0\n    while i < len(s):\n        best_len = best_off = 0\n        for j in range(max(0, i - window), i):\n            l = 0\n            while i + l < len(s) - 1 and s[j + l] == s[i + l]:    # keep one char for the literal\n                l += 1\n            if l > best_len:\n                best_len, best_off = l, i - j\n        out.append((best_off, best_len, s[i + best_len]))\n        i += best_len + 1\n    return out\n\ndef lz77_decode(tokens):\n    out = []\n    for off, ln, ch in tokens:\n        start = len(out) - off\n        for k in range(ln):\n            out.append(out[start + k])                              # overlap-safe: reads what was just written\n        out.append(ch)\n    return \"\".join(out)\n\ntok = lz77_encode(\"aacaacabcabaaac\")\nprint(tok, lz77_decode(tok))"}, "check": "import random\nassert lz77_decode(lz77_encode(\"aaaaaaaa\")) == \"aaaaaaaa\" and lz77_encode(\"\") == []\nassert lz77_encode(\"aaaa\") == [(0, 0, \"a\"), (1, 2, \"a\")]\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 30)))\n    assert lz77_decode(lz77_encode(s, window=random.randint(1, 10))) == s", "more": "- Offset 0 with length 0 is a pure literal.\n- Overlapping copies are legal: (\"aaaa\" is a literal then offset 1, length 2).\n- The brute-force match search here is O(window) per position; real compressors use hash chains or suffix structures to find matches.\n- Output tokens are then entropy-coded (DEFLATE = LZ77 + Huffman).\n- Closest relatives: LZ78 and LZW, which build an explicit dictionary instead of a window.", "cx": "Encode O(n * window * match length) as written (faster with hashing); decode O(n). Space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-lz78", "title": "LZ78 compression", "cat": "Strings: sequence alignment and compression", "q": ["what is LZ78", "explain LZ78", "how does LZ78 work", "LZ78 in python", "implement LZ78", "LZ78 code", "when to use LZ78", "lz78 vs lzw", "dictionary based compression"], "tags": "lz78 dictionary compression index character pairs trie phrase parsing", "a": "LZ78 builds a dictionary of phrases while it scans. Each output token is (index of the longest known phrase, next character), and the extended phrase is added to the dictionary. The decoder rebuilds the same dictionary from the tokens, so nothing else is transmitted.", "code": {"py": "def lz78_encode(s):\n    d, out, w = {\"\": 0}, [], \"\"\n    for c in s:\n        if w + c in d:\n            w += c\n        else:\n            out.append((d[w], c))\n            d[w + c] = len(d)\n            w = \"\"\n    if w:                                         # leftover phrase already in the dictionary\n        out.append((d[w[:-1]], w[-1]))\n    return out\n\ndef lz78_decode(tokens):\n    phrases, out = [\"\"], []\n    for idx, c in tokens:\n        p = phrases[idx] + c\n        phrases.append(p); out.append(p)\n    return \"\".join(out)\n\ntok = lz78_encode(\"abababab\")\nprint(tok, lz78_decode(tok))  # [(0, 'a'), (0, 'b'), (1, 'b'), (3, 'a'), (0, 'b')] abababab"}, "check": "import random\nassert lz78_encode(\"abababab\") == [(0, \"a\"), (0, \"b\"), (1, \"b\"), (3, \"a\"), (0, \"b\")]\nassert lz78_encode(\"\") == [] and lz78_decode([]) == \"\"\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 30)))\n    assert lz78_decode(lz78_encode(s)) == s", "more": "- Every phrase is an earlier phrase plus one character, so the dictionary is a trie; a dict of strings is the simple version.\n- Dictionary growth is unbounded; practical coders cap it and reset.\n- Leftover handling: the final phrase may already exist, so it is emitted as (parent, last char) and the decoder harmlessly adds a duplicate.\n- Compared with LZ77: no window and no search, but the dictionary learns slowly.", "cx": "Encode O(n) expected with hashing (each lookup hashes a phrase string, so O(n * average phrase length) in Python); decode O(n). Space O(number of phrases).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-lzw", "title": "LZW compression (encode and decode)", "cat": "Strings: sequence alignment and compression", "q": ["what is LZW", "explain LZW", "how does LZW work", "LZW in python", "implement LZW", "LZW code", "when to use LZW", "lempel ziv welch", "lzw round trip", "lzw decode special case"], "tags": "lzw lempel ziv welch compression dictionary codes gif encode decode round trip", "a": "LZW starts with a dictionary of all single bytes. It emits the code of the longest known phrase and adds phrase + next byte as a new code, so no characters are sent explicitly. The decoder rebuilds the same dictionary; the one tricky case is a code that refers to the entry being created right now.", "code": {"py": "def lzw_encode(data: bytes):\n    d = {bytes([i]): i for i in range(256)}\n    w, out = b\"\", []\n    for b in data:\n        wc = w + bytes([b])\n        if wc in d:\n            w = wc\n        else:\n            out.append(d[w])\n            d[wc] = len(d)\n            w = bytes([b])\n    if w:\n        out.append(d[w])\n    return out\n\ndef lzw_decode(codes):\n    if not codes:\n        return b\"\"\n    d = {i: bytes([i]) for i in range(256)}\n    w = d[codes[0]]\n    out = [w]\n    for c in codes[1:]:\n        e = d[c] if c in d else w + w[:1]        # code not yet known: it is w + first char of w\n        out.append(e)\n        d[len(d)] = w + e[:1]\n        w = e\n    return b\"\".join(out)\n\ncodes = lzw_encode(b\"TOBEORNOTTOBEORTOBEORNOT\")\nprint(len(codes), lzw_decode(codes))  # 16 b'TOBEORNOTTOBEORTOBEORNOT'"}, "check": "import random\nassert lzw_decode(lzw_encode(b\"aaaaaaa\")) == b\"aaaaaaa\" and lzw_encode(b\"\") == [] and lzw_decode([]) == b\"\"\nassert len(lzw_encode(b\"TOBEORNOTTOBEORTOBEORNOT\")) == 16\nfor _ in range(500):\n    data = bytes(random.choice(b\"abc\") for _ in range(random.randint(0, 40)))\n    assert lzw_decode(lzw_encode(data)) == data", "more": "- The decoder is always one entry behind the encoder; when it sees a code equal to the next free index (pattern like \"aaa\"), the entry must be w + w[0].\n- Real formats (GIF, TIFF) pack codes into variable-width bit fields and reset the table when full.\n- Highly repetitive data compresses well; random data can expand.\n- Closest alternatives: LZ77 (window based), LZ78 (explicit next character).", "cx": "Encode and decode O(n) expected (dictionary operations on byte strings); space O(number of codes).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-rle", "title": "Run-length encoding", "cat": "Strings: sequence alignment and compression", "q": ["what is run-length encoding", "explain run-length encoding", "how does run-length encoding work", "run-length encoding in python", "implement run-length encoding", "run-length encoding code", "when to use run-length encoding", "string compression aaabb to a3b2", "compress repeated characters"], "tags": "run length encoding rle compress repeated characters groupby count string compression leetcode 443", "a": "Run-length encoding replaces each run of identical characters with count + character (\"aaabb\" becomes \"3a2b\"). Use itertools.groupby to find runs. It only helps data with long runs; for text with digits you need pairs instead of a flat string, otherwise the decoder cannot tell counts from data.", "code": {"py": "import re\nfrom itertools import groupby\n\ndef rle_encode(s):\n    return \"\".join(f\"{sum(1 for _ in g)}{c}\" for c, g in groupby(s))\n\ndef rle_decode(e):\n    return \"\".join(c * int(n) for n, c in re.findall(r\"(\\d+)(\\D)\", e))\n\ndef rle_pairs(s):\n    \"\"\"Safe for any characters: a list of (char, run length).\"\"\"\n    return [(c, sum(1 for _ in g)) for c, g in groupby(s)]\n\nprint(rle_encode(\"aaabccdddd\"))  # 3a1b2c4d"}, "check": "import random\nassert rle_encode(\"aaabccdddd\") == \"3a1b2c4d\" and rle_encode(\"\") == \"\" and rle_decode(\"3a1b2c4d\") == \"aaabccdddd\"\nassert rle_pairs(\"aab\") == [(\"a\", 2), (\"b\", 1)]\nfor _ in range(300):\n    s = \"\".join(random.choice(\"abc \") for _ in range(random.randint(0, 25)))\n    assert rle_decode(rle_encode(s)) == s\n    assert \"\".join(c * n for c, n in rle_pairs(s)) == s", "more": "- Worst case doubles the size (no runs: \"abc\" becomes \"1a1b1c\"), so real formats mark literals separately.\n- Interview variant: compress in place and write counts only when greater than 1 (LeetCode 443); keep the read and write pointers apart.\n- Counts above 9 are multi-digit; that is why the decoder uses a regex for digits then one non-digit.\n- RLE after a Burrows-Wheeler transform is a classic pipeline (bzip2).", "cx": "Time O(n), space O(n) output.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-bwt", "title": "Burrows-Wheeler transform and its inverse", "cat": "Strings: sequence alignment and compression", "q": ["what is Burrows-Wheeler transform", "explain Burrows-Wheeler transform", "how does Burrows-Wheeler transform work", "Burrows-Wheeler transform in python", "implement Burrows-Wheeler transform", "Burrows-Wheeler transform code", "when to use Burrows-Wheeler transform", "bwt", "bzip2 algorithm idea", "inverse burrows wheeler"], "tags": "burrows wheeler transform bwt inverse lf mapping rotations sorted last column bzip2 fm index", "a": "The Burrows-Wheeler transform sorts all rotations of the text (plus a unique end marker) and outputs the last column. Equal contexts end up grouped, so the result compresses well with run-length and move-to-front coding. It is reversible: sort the output to get the first column and follow the LF mapping.", "code": {"py": "def bwt(s, end=\"$\"):\n    assert end not in s\n    t = s + end\n    rots = sorted(range(len(t)), key=lambda i: t[i:] + t[:i])\n    return \"\".join(t[i - 1] for i in rots)\n\ndef ibwt(last, end=\"$\"):\n    n = len(last)\n    order = sorted(range(n), key=lambda i: (last[i], i))     # stable: k-th char of the first column comes from last[order[k]]\n    lf = [0] * n\n    for k, i in enumerate(order):\n        lf[i] = k\n    r, out = last.index(end), []                              # the row that ends with the marker is the original string\n    for _ in range(n):\n        out.append(last[r])\n        r = lf[r]\n    return \"\".join(reversed(out))[:-1]\n\nprint(bwt(\"banana\"))  # annb$aa"}, "check": "import random\nassert bwt(\"banana\") == \"annb$aa\" and ibwt(\"annb$aa\") == \"banana\" and ibwt(bwt(\"\")) == \"\"\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 15)))\n    assert ibwt(bwt(s)) == s", "more": "- Why invertible: the first column is just the sorted last column, and the k-th occurrence of a letter in the last column is the same text character as the k-th occurrence in the first (the LF property).\n- The marker must be unique; without it you must also store the index of the original rotation.\n- The sort above is O(n^2 log n) worst case; real implementations build a suffix array instead.\n- The same structure powers FM-index search (count pattern occurrences by backward search).", "cx": "Naive transform O(n^2 log n) time (O(n) with a suffix array construction), inverse O(n log n) with a sort (O(n) with counting). Space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-move-to-front", "title": "Move-to-front transform", "cat": "Strings: sequence alignment and compression", "q": ["what is move-to-front", "explain move-to-front", "how does move-to-front work", "move-to-front in python", "implement move-to-front", "move-to-front code", "when to use move-to-front", "mtf"], "tags": "move to front mtf transform recency rank list compression after bwt", "a": "Move-to-front keeps a list of symbols and replaces each input symbol by its current position, then moves that symbol to the front. Recently used symbols get small numbers, so repetitive data (like the output of a Burrows-Wheeler transform) turns into many zeros that compress well.", "code": {"py": "def mtf_encode(s, alphabet):\n    table, out = list(alphabet), []\n    for c in s:\n        i = table.index(c)\n        out.append(i)\n        table.insert(0, table.pop(i))\n    return out\n\ndef mtf_decode(codes, alphabet):\n    table, out = list(alphabet), []\n    for i in codes:\n        c = table[i]\n        out.append(c)\n        table.insert(0, table.pop(i))\n    return \"\".join(out)\n\nprint(mtf_encode(\"bananaaa\", \"abn\"))  # [1, 1, 2, 1, 1, 1, 0, 0]"}, "check": "import random\nA = \"abcd\"\nassert mtf_encode(\"bananaaa\", \"abn\") == [1, 1, 2, 1, 1, 1, 0, 0] and mtf_encode(\"\", A) == []\nfor _ in range(500):\n    s = \"\".join(random.choice(A) for _ in range(random.randint(0, 20)))\n    assert mtf_decode(mtf_encode(s, A), A) == s", "more": "- Both sides must start from the same alphabet order.\n- A run of the same symbol becomes one rank then zeros.\n- Each step costs O(alphabet) with a list; fine for 256 symbols.\n- It does not compress by itself, it just skews the distribution so a later Huffman or arithmetic stage works better.", "cx": "Time O(n * alphabet size), space O(alphabet).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-base64", "title": "Base64 encoding and decoding", "cat": "Strings: sequence alignment and compression", "q": ["what is Base64", "explain Base64", "how does Base64 work", "Base64 in python", "implement Base64", "Base64 code", "when to use Base64", "base64 encode manually", "how does base64 work", "base64 padding equals sign"], "tags": "base64 encoding decoding 6 bit groups padding equals b64encode binary to text", "a": "Base64 turns every 3 bytes (24 bits) into 4 characters from a 64-letter alphabet, by splitting the 24 bits into four 6-bit groups. If the input length is not a multiple of 3, the output is padded with \"=\" to a multiple of 4. In real code use the `base64` module.", "code": {"py": "import base64\n\nALPHA = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"\n\ndef b64_encode(data: bytes) -> str:\n    out = []\n    for i in range(0, len(data), 3):\n        chunk = data[i:i + 3]\n        n = int.from_bytes(chunk.ljust(3, b\"\\0\"), \"big\")\n        quad = \"\".join(ALPHA[(n >> sh) & 63] for sh in (18, 12, 6, 0))\n        pad = 3 - len(chunk)\n        out.append(quad[:4 - pad] + \"=\" * pad)\n    return \"\".join(out)\n\ndef b64_decode(s: str) -> bytes:\n    acc = bits = 0\n    out = bytearray()\n    for ch in s.rstrip(\"=\"):\n        acc = (acc << 6) | ALPHA.index(ch)\n        bits += 6\n        if bits >= 8:\n            bits -= 8\n            out.append((acc >> bits) & 255)\n            acc &= (1 << bits) - 1\n    return bytes(out)\n\nprint(b64_encode(b\"Man\"), b64_encode(b\"Ma\"), base64.b64encode(b\"Ma\").decode())  # TWFu TWE= TWE="}, "check": "import os, random, base64\nfor n in range(0, 20):\n    data = os.urandom(n)\n    assert b64_encode(data) == base64.b64encode(data).decode()\n    assert b64_decode(b64_encode(data)) == data\nassert b64_encode(b\"Man\") == \"TWFu\" and b64_encode(b\"M\") == \"TQ==\" and b64_decode(\"TWE=\") == b\"Ma\"", "more": "- 3 bytes in, 4 characters out: output is about 33 percent larger.\n- Padding: 1 leftover byte gives \"==\", 2 leftover bytes give \"=\".\n- URL-safe variant swaps \"+\" and \"/\" for \"-\" and \"_\" (`base64.urlsafe_b64encode`).\n- Base64 is an encoding, not encryption.\n- Decoding to text needs `.decode(\"utf-8\")` afterwards.", "cx": "Time O(n), space O(n).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-varint", "title": "Varint (LEB128) and zigzag encoding", "cat": "Strings: sequence alignment and compression", "q": ["what is varint", "explain varint", "how does varint work", "varint in python", "implement varint", "varint code", "when to use varint", "leb128", "protobuf varint", "variable length integer encoding"], "tags": "varint leb128 variable length integer protobuf zigzag encoding 7 bits continuation", "a": "A varint stores an integer in 7-bit groups, least significant group first, with the top bit of each byte meaning \"more bytes follow\". Small numbers take one byte. For signed integers, zigzag first maps 0, -1, 1, -2 ... to 0, 1, 2, 3 ... so small negatives stay small.", "code": {"py": "def varint_encode(n):\n    assert n >= 0\n    out = bytearray()\n    while True:\n        b = n & 0x7F\n        n >>= 7\n        if n:\n            out.append(b | 0x80)       # continuation bit\n        else:\n            out.append(b)\n            return bytes(out)\n\ndef varint_decode(data, pos=0):\n    n = shift = 0\n    while True:\n        b = data[pos]; pos += 1\n        n |= (b & 0x7F) << shift\n        if not b & 0x80:\n            return n, pos\n        shift += 7\n\ndef zigzag(n):   return n * 2 if n >= 0 else -n * 2 - 1\ndef unzigzag(z): return z // 2 if z % 2 == 0 else -(z + 1) // 2\n\nprint(varint_encode(300).hex(), [zigzag(x) for x in (0, -1, 1, -2)])  # ac02 [0, 1, 2, 3]"}, "check": "import random\nassert varint_encode(0) == b\"\\x00\" and varint_encode(127) == b\"\\x7f\" and varint_encode(128) == b\"\\x80\\x01\"\nassert varint_encode(300) == b\"\\xac\\x02\" and varint_decode(b\"\\xac\\x02\") == (300, 2)\nfor _ in range(1000):\n    n = random.randint(0, 1 << random.randint(1, 70))\n    e = varint_encode(n)\n    assert varint_decode(b\"xx\" + e, 2) == (n, 2 + len(e))\n    z = random.randint(-(1 << 40), 1 << 40)\n    assert unzigzag(zigzag(z)) == z and zigzag(z) >= 0", "more": "- Each byte carries 7 data bits, so values below 128 take 1 byte, below 16384 take 2, and so on.\n- Decode loop: add (byte & 0x7F) << shift, stop at the first byte with a clear top bit.\n- Without zigzag a negative number in two's complement would always take the maximum number of bytes.\n- Used in Protocol Buffers, WebAssembly, DWARF and many index formats.", "cx": "Time O(number of bytes) = O(log n) per value, space O(1) extra.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-elias-gamma", "title": "Elias gamma coding", "cat": "Strings: sequence alignment and compression", "q": ["what is Elias gamma code", "explain Elias gamma code", "how does Elias gamma code work", "Elias gamma code in python", "implement Elias gamma code", "Elias gamma code code", "when to use Elias gamma code", "universal codes", "elias gamma vs delta", "encode gaps in inverted index"], "tags": "elias gamma code universal code unary length binary positive integers bit string inverted index", "a": "Elias gamma encodes a positive integer n as (bit length - 1) zeros followed by the binary form of n: 1 becomes \"1\", 2 becomes \"010\", 5 becomes \"00101\". It needs no table and favours small numbers, so it suits gaps in sorted postings lists.", "code": {"py": "def gamma_encode(n):\n    assert n >= 1\n    b = format(n, \"b\")\n    return \"0\" * (len(b) - 1) + b\n\ndef gamma_decode(bits):\n    out, i = [], 0\n    while i < len(bits):\n        z = 0\n        while bits[i] == \"0\":\n            z += 1; i += 1\n        out.append(int(bits[i:i + z + 1], 2))\n        i += z + 1\n    return out\n\nstream = \"\".join(gamma_encode(n) for n in (1, 2, 5, 9))\nprint(stream, gamma_decode(stream))  # 1010001010001001 [1, 2, 5, 9]"}, "check": "import random\nassert gamma_encode(1) == \"1\" and gamma_encode(2) == \"010\" and gamma_encode(5) == \"00101\" and gamma_decode(\"\") == []\nfor _ in range(500):\n    nums = [random.randint(1, 1 << random.randint(1, 20)) for _ in range(random.randint(0, 8))]\n    assert gamma_decode(\"\".join(map(gamma_encode, nums))) == nums\n    assert all(len(gamma_encode(n)) == 2 * n.bit_length() - 1 for n in nums)", "more": "- The zero run tells the decoder how many more bits follow, which makes the code prefix-free and self-delimiting.\n- Length is 2*floor(log2 n) + 1 bits; Elias delta code is shorter for large values.\n- It cannot encode 0; shift values by 1 (encode n + 1).\n- Typical use: encode the gaps between sorted document ids in a search index.", "cx": "Time O(log n) per value, space O(log n) bits.", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-soundex", "title": "Soundex (and the Metaphone idea)", "cat": "Strings: sequence alignment and compression", "q": ["what is Soundex", "explain Soundex", "how does Soundex work", "Soundex in python", "implement Soundex", "Soundex code", "when to use Soundex", "phonetic matching of names", "metaphone", "sounds like algorithm"], "tags": "soundex phonetic encoding similar sounding names metaphone double metaphone phonetic matching", "a": "Soundex maps a name to a letter plus three digits so similar-sounding names collide: keep the first letter, map consonants to digit classes (BFPV 1, CGJKQSXZ 2, DT 3, L 4, MN 5, R 6), drop vowels, collapse adjacent equal codes, pad with zeros. Metaphone applies spelling-to-sound rules instead and is more accurate for English.", "code": {"py": "CODES = {c: d for d, letters in {\"1\": \"bfpv\", \"2\": \"cgjkqsxz\", \"3\": \"dt\", \"4\": \"l\", \"5\": \"mn\", \"6\": \"r\"}.items() for c in letters}\n\ndef soundex(name):\n    name = \"\".join(c for c in name.lower() if c.isalpha())\n    if not name:\n        return \"\"\n    out, prev = name[0].upper(), CODES.get(name[0], \"\")\n    for ch in name[1:]:\n        code = CODES.get(ch, \"\")\n        if code and code != prev:\n            out += code\n        if ch not in \"hw\":              # h and w do not separate equal codes; vowels do\n            prev = code\n    return (out + \"000\")[:4]\n\nprint(soundex(\"Robert\"), soundex(\"Rupert\"), soundex(\"Tymczak\"))  # R163 R163 T522"}, "check": "exp = {\"Robert\": \"R163\", \"Rupert\": \"R163\", \"Rubin\": \"R150\", \"Ashcraft\": \"A261\", \"Tymczak\": \"T522\",\n       \"Pfister\": \"P236\", \"Honeyman\": \"H555\", \"Lee\": \"L000\", \"\": \"\"}\nfor name, code in exp.items():\n    assert soundex(name) == code, (name, soundex(name))\nassert soundex(\"o'Brien\") == soundex(\"OBrien\")", "more": "- Vowels reset the \"previous code\", so two equal consonant codes separated by a vowel both count; h and w do not reset (Ashcraft is A261, not A226).\n- The first letter keeps its own letter but its code still blocks an identical code right after it (Pfister is P236).\n- Soundex is designed for English surnames; it is coarse and gives false matches. Metaphone and Double Metaphone handle more spelling patterns, and edit distance handles typos.\n- Use it as a cheap blocking key before a more precise comparison.", "cx": "Time O(length of name), space O(1).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-ngram-similarity", "title": "N-gram similarity (Jaccard and Dice)", "cat": "Strings: sequence alignment and compression", "q": ["what is n-gram similarity", "explain n-gram similarity", "how does n-gram similarity work", "n-gram similarity in python", "implement n-gram similarity", "n-gram similarity code", "when to use n-gram similarity", "string similarity jaccard", "dice coefficient strings", "bigram similarity"], "tags": "n-gram similarity jaccard dice coefficient bigram trigram set overlap string similarity fuzzy duplicate", "a": "Split each string into overlapping n-grams (usually 2 or 3 characters) and compare the sets. Jaccard = |A and B| / |A or B|; Dice = 2|A and B| / (|A| + |B|). Both are 1 for identical sets and 0 for none shared, and they tolerate small typos and word-order changes better than exact match.", "code": {"py": "from fractions import Fraction\n\ndef ngrams(s, n=2):\n    return {s[i:i + n] for i in range(len(s) - n + 1)}\n\ndef jaccard(a, b, n=2):\n    A, B = ngrams(a, n), ngrams(b, n)\n    return Fraction(len(A & B), len(A | B)) if A | B else Fraction(1)\n\ndef dice(a, b, n=2):\n    A, B = ngrams(a, n), ngrams(b, n)\n    return Fraction(2 * len(A & B), len(A) + len(B)) if A or B else Fraction(1)\n\nprint(jaccard(\"night\", \"nacht\"), dice(\"night\", \"nacht\"))  # 1/7 1/4"}, "check": "import random\nassert jaccard(\"night\", \"nacht\") == Fraction(1, 7) and dice(\"night\", \"nacht\") == Fraction(1, 4)\nassert jaccard(\"abc\", \"abc\") == 1 and dice(\"abc\", \"xyz\") == 0 and jaccard(\"\", \"\") == 1\nfor _ in range(300):\n    a = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    b = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 8)))\n    j, d = jaccard(a, b), dice(a, b)\n    assert 0 <= j <= d <= 1 or (j == d == 1)\n    assert d == 2 * j / (1 + j)", "more": "- Dice and Jaccard are monotone in each other: Dice = 2J / (1 + J), so they rank pairs identically.\n- Using sets ignores repeated n-grams; use multisets (Counter) when counts matter.\n- Strings shorter than n have no n-grams; pad with a boundary marker or use a smaller n.\n- Lower n tolerates typos more, higher n is stricter. For large collections, hash the n-grams (MinHash) instead of comparing every pair.", "cx": "Time O(len(a) + len(b)) with hashed sets, space O(len(a) + len(b)).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-text-justification", "title": "Text justification (greedy)", "cat": "Strings: sequence alignment and compression", "q": ["what is text justification", "explain text justification", "how does text justification work", "text justification in python", "implement text justification", "text justification code", "when to use text justification", "leetcode 68", "justify text lines to fixed width"], "tags": "text justification greedy pack words full justify fully justified lines width leetcode 68 spaces distribute", "a": "Pack as many words as fit on each line (greedy, one space between words minimum), then distribute the leftover spaces evenly across the gaps, giving extra spaces to the leftmost gaps. The last line, and any line with one word, is left-justified and padded on the right.", "code": {"py": "def full_justify(words, width):\n    res, i = [], 0\n    while i < len(words):\n        j, length = i, len(words[i])\n        while j + 1 < len(words) and length + 1 + len(words[j + 1]) <= width:\n            j += 1\n            length += 1 + len(words[j])\n        line, gaps = words[i:j + 1], j - i\n        if j == len(words) - 1 or gaps == 0:\n            res.append(\" \".join(line).ljust(width))\n        else:\n            q, r = divmod(width - sum(map(len, line)), gaps)\n            res.append(\"\".join(w + \" \" * (q + (k < r)) for k, w in enumerate(line[:-1])) + line[-1])\n        i = j + 1\n    return res\n\nprint(full_justify([\"This\", \"is\", \"an\", \"example\", \"of\", \"text\", \"justification.\"], 16))"}, "check": "ws = [\"This\", \"is\", \"an\", \"example\", \"of\", \"text\", \"justification.\"]\nassert full_justify(ws, 16) == [\"This    is    an\", \"example  of text\", \"justification.  \"]\nassert full_justify([\"a\"], 3) == [\"a  \"] and full_justify([], 5) == []\nr = full_justify([\"What\", \"must\", \"be\", \"acknowledgment\", \"shall\", \"be\"], 16)\nassert r == [\"What   must   be\", \"acknowledgment  \", \"shall be        \"]\nassert all(len(l) == 16 for l in r)", "more": "- Greedy packing is what the problem asks for; it does not minimize raggedness (see the word-wrap DP entry).\n- Extra spaces go to the left gaps first: divmod(total spaces, gaps) gives (base, remainder).\n- Edge cases: a single word per line, last line, empty input.\n- Common mistake: adding the trailing space of the last word when testing whether it fits (use length + 1 + len(next) <= width).", "cx": "Time O(total characters), space O(output).", "see": ["#/topic/string-algos", "#/cheatsheets/big-o-algorithms"]},
    {"id": "cs2-word-wrap-dp", "title": "Word wrap with minimum raggedness (DP)", "cat": "Strings: sequence alignment and compression", "q": ["what is word wrap dynamic programming", "explain word wrap dynamic programming", "how does word wrap dynamic programming work", "word wrap dynamic programming in python", "implement word wrap dynamic programming", "word wrap dynamic programming code", "when to use word wrap dynamic programming", "minimum raggedness", "optimal line breaking", "knuth plass idea"], "tags": "word wrap minimum raggedness dp minimize sum of squares of trailing spaces line breaking optimal", "a": "Break a paragraph into lines of at most W characters minimizing the sum of squared leftover spaces (the last line is free). Let best[i] be the minimum cost to lay out words[i:]; try every line that starts at i and fits, cost (W - line length)^2 + best[j+1]. Remember the choice to rebuild the lines.", "code": {"py": "def word_wrap(words, width):\n    n = len(words)\n    assert all(len(w) <= width for w in words)\n    INF = float(\"inf\")\n    best, nxt = [0] * (n + 1), [n] * (n + 1)\n    for i in range(n - 1, -1, -1):\n        best[i], length = INF, -1\n        for j in range(i, n):\n            length += 1 + len(words[j])\n            if length > width:\n                break\n            cost = 0 if j == n - 1 else (width - length) ** 2\n            if cost + best[j + 1] < best[i]:\n                best[i], nxt[i] = cost + best[j + 1], j + 1\n    lines, i = [], 0\n    while i < n:\n        lines.append(\" \".join(words[i:nxt[i]])); i = nxt[i]\n    return best[0], lines\n\nprint(word_wrap(\"aaa bb cc ddddd\".split(), 6))  # (10, ['aaa', 'bb cc', 'ddddd'])"}, "check": "import random\nfrom functools import lru_cache\ncost, lines = word_wrap(\"aaa bb cc ddddd\".split(), 6)\nassert lines == [\"aaa\", \"bb cc\", \"ddddd\"] and cost == 9 + 1\nassert word_wrap([], 5) == (0, [])\nfor _ in range(300):\n    ws = [\"x\" * random.randint(1, 5) for _ in range(random.randint(0, 8))]\n    W = random.randint(5, 12)\n    @lru_cache(None)\n    def brute(i):\n        if i == len(ws): return 0\n        res, ln = float(\"inf\"), -1\n        for j in range(i, len(ws)):\n            ln += 1 + len(ws[j])\n            if ln > W: break\n            res = min(res, (0 if j == len(ws) - 1 else (W - ln) ** 2) + brute(j + 1))\n        return res\n    c, ls = word_wrap(ws, W)\n    assert c == brute(0) and \" \".join(ls).split() == ws and all(len(l) <= W for l in ls)", "more": "- Squaring the leftover spaces punishes one very short line much more than several slightly short ones, which a greedy fill does not avoid.\n- Not counting the last line stops the paragraph end from being forced to fill.\n- With n words and at most W/2 words per line the inner loop is bounded, so time is O(n * W) in practice.\n- This is the idea behind the Knuth-Plass line-breaking algorithm used by TeX.", "cx": "Time O(n^2) worst case (O(n * W) since a line holds at most W/2 words), space O(n).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-longest-palindromic-subsequence", "title": "Longest palindromic subsequence", "cat": "Strings: sequence alignment and compression", "q": ["what is longest palindromic subsequence", "explain longest palindromic subsequence", "how does longest palindromic subsequence work", "longest palindromic subsequence in python", "implement longest palindromic subsequence", "longest palindromic subsequence code", "when to use longest palindromic subsequence", "leetcode 516", "palindromic subsequence vs substring", "minimum insertions to make palindrome"], "tags": "longest palindromic subsequence lps interval dp leetcode 516 palindrome subsequence reverse lcs", "a": "Longest palindromic subsequence (characters may be non-contiguous). Interval DP: dp[i][j] is the answer for s[i..j]; if s[i] == s[j] it is 2 + dp[i+1][j-1], else max(dp[i+1][j], dp[i][j-1]). Equivalently it is the LCS of s and its reverse.", "code": {"py": "def longest_palindromic_subsequence(s):\n    n = len(s)\n    if n == 0:\n        return \"\"\n    dp = [[0] * n for _ in range(n)]\n    for i in range(n - 1, -1, -1):\n        dp[i][i] = 1\n        for j in range(i + 1, n):\n            dp[i][j] = dp[i + 1][j - 1] + 2 if s[i] == s[j] else max(dp[i + 1][j], dp[i][j - 1])\n    left, mid, i, j = [], \"\", 0, n - 1\n    while i <= j:                                   # rebuild one optimal palindrome\n        if i == j:\n            mid = s[i]; break\n        if s[i] == s[j]:\n            left.append(s[i]); i += 1; j -= 1\n        elif dp[i + 1][j] >= dp[i][j - 1]:\n            i += 1\n        else:\n            j -= 1\n    return \"\".join(left) + mid + \"\".join(reversed(left))\n\nprint(longest_palindromic_subsequence(\"bbbab\"))  # bbbb"}, "check": "import random\nfrom itertools import combinations\nassert longest_palindromic_subsequence(\"bbbab\") == \"bbbb\" and longest_palindromic_subsequence(\"\") == \"\"\nassert len(longest_palindromic_subsequence(\"cbbd\")) == 2\nfor _ in range(300):\n    s = \"\".join(random.choice(\"abc\") for _ in range(random.randint(0, 9)))\n    r = longest_palindromic_subsequence(s)\n    brute = max(len(t) for k in range(len(s) + 1) for c in combinations(s, k) for t in [\"\".join(c)] if t == t[::-1])\n    it = iter(s)\n    assert len(r) == brute and r == r[::-1] and all(ch in it for ch in r), (s, r)", "more": "- Subsequence versus substring: \"bbbb\" is a subsequence of \"bbbab\" but not a substring; the longest palindromic substring needs Manacher or expand-around-center instead.\n- Fill i from n-1 down to 0 so dp[i+1][*] is ready; dp[i+1][j-1] for j = i+1 is the empty range (0).\n- Related: minimum insertions to make a string a palindrome = n - LPS.\n- Space can drop to O(n) with two rows, but then you lose the reconstruction.", "cx": "Time O(n^2), space O(n^2).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-shortest-common-supersequence", "title": "Shortest common supersequence", "cat": "Strings: sequence alignment and compression", "q": ["what is shortest common supersequence", "explain shortest common supersequence", "how does shortest common supersequence work", "shortest common supersequence in python", "implement shortest common supersequence", "shortest common supersequence code", "when to use shortest common supersequence", "leetcode 1092", "smallest string with both as subsequence", "merge two strings with minimum length"], "tags": "shortest common supersequence scs leetcode 1092 merge two strings keep both as subsequences lcs length n+m-lcs", "a": "The shortest string containing both a and b as subsequences has length len(a) + len(b) - LCS(a, b). Build the LCS table, then walk back from the corner: equal characters are emitted once, otherwise emit the character from the side you step away from, and finally append whatever remains.", "code": {"py": "def shortest_common_supersequence(a, b):\n    n, m = len(a), len(b)\n    dp = [[0] * (m + 1) for _ in range(n + 1)]\n    for i in range(n):\n        for j in range(m):\n            dp[i + 1][j + 1] = dp[i][j] + 1 if a[i] == b[j] else max(dp[i][j + 1], dp[i + 1][j])\n    out, i, j = [], n, m\n    while i and j:\n        if a[i - 1] == b[j - 1]:\n            out.append(a[i - 1]); i -= 1; j -= 1\n        elif dp[i - 1][j] >= dp[i][j - 1]:\n            out.append(a[i - 1]); i -= 1\n        else:\n            out.append(b[j - 1]); j -= 1\n    out.extend(reversed(a[:i])); out.extend(reversed(b[:j]))\n    return \"\".join(reversed(out))\n\nprint(shortest_common_supersequence(\"abac\", \"cab\"))  # cabac"}, "check": "import random\nfrom itertools import product\ndef is_sub(s, t):\n    it = iter(t); return all(c in it for c in s)\nr = shortest_common_supersequence(\"abac\", \"cab\")\nassert len(r) == 5 and is_sub(\"abac\", r) and is_sub(\"cab\", r)\nassert shortest_common_supersequence(\"\", \"ab\") == \"ab\" and shortest_common_supersequence(\"a\", \"a\") == \"a\"\nfor _ in range(200):\n    a = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 5)))\n    b = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 5)))\n    r = shortest_common_supersequence(a, b)\n    assert is_sub(a, r) and is_sub(b, r)\n    best = next(L for L in range(len(a) + len(b) + 1) if any(is_sub(a, \"\".join(t)) and is_sub(b, \"\".join(t)) for t in product(\"ab\", repeat=L)))\n    assert len(r) == best, (a, b, r)", "more": "- Characters in the LCS are shared (written once); every other character of a or b is written once as well, hence n + m - LCS.\n- The answer is generally not unique when ties occur in the table.\n- Two strings only; for many strings the problem is NP-hard.\n- Not to be confused with merging by interleaving (interleaving keeps both strings as exact, disjoint subsequences).", "cx": "Time O(nm), space O(nm).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-interleaving-strings", "title": "Interleaving string (is c an interleave of a and b)", "cat": "Strings: sequence alignment and compression", "q": ["what is interleaving strings", "explain interleaving strings", "how does interleaving strings work", "interleaving strings in python", "implement interleaving strings", "interleaving strings code", "when to use interleaving strings", "leetcode 97", "merge two strings keeping order check"], "tags": "interleaving string interleave two strings dp leetcode 97 merge preserving order 2d dp", "a": "Decide whether c can be formed by merging a and b while keeping each string's own order. DP over how many characters of a (i) and b (j) have been used: dp[i][j] is true if c[:i+j] is an interleaving of a[:i] and b[:j], reached from dp[i-1][j] if a[i-1] == c[i+j-1], or from dp[i][j-1] if b[j-1] == c[i+j-1].", "code": {"py": "def is_interleave(a, b, c):\n    if len(a) + len(b) != len(c):\n        return False\n    dp = [False] * (len(b) + 1)               # dp[j] for the current i\n    dp[0] = True\n    for j in range(1, len(b) + 1):\n        dp[j] = dp[j - 1] and b[j - 1] == c[j - 1]\n    for i in range(1, len(a) + 1):\n        dp[0] = dp[0] and a[i - 1] == c[i - 1]\n        for j in range(1, len(b) + 1):\n            k = i + j - 1\n            dp[j] = (dp[j] and a[i - 1] == c[k]) or (dp[j - 1] and b[j - 1] == c[k])\n    return dp[len(b)]\n\nprint(is_interleave(\"aabcc\", \"dbbca\", \"aadbbcbcac\"), is_interleave(\"aabcc\", \"dbbca\", \"aadbbbaccc\"))  # True False"}, "check": "import random\nfrom functools import lru_cache\nassert is_interleave(\"aabcc\", \"dbbca\", \"aadbbcbcac\") and not is_interleave(\"aabcc\", \"dbbca\", \"aadbbbaccc\")\nassert is_interleave(\"\", \"\", \"\") and not is_interleave(\"a\", \"\", \"b\")\nfor _ in range(500):\n    a = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 5)))\n    b = \"\".join(random.choice(\"ab\") for _ in range(random.randint(0, 5)))\n    c = \"\".join(random.choice(\"ab\") for _ in range(len(a) + len(b) + random.choice([0, 0, 0, 1])))\n    @lru_cache(None)\n    def go(i, j):\n        k = i + j\n        if k == len(c): return i == len(a) and j == len(b)\n        return (i < len(a) and a[i] == c[k] and go(i + 1, j)) or (j < len(b) and b[j] == c[k] and go(i, j + 1))\n    assert is_interleave(a, b, c) == bool(go(0, 0)), (a, b, c)", "more": "- A greedy \"take from a if it matches\" fails when both strings can supply the next character; the DP keeps both options alive.\n- Quick reject: lengths must add up and the multiset of letters must match.\n- The 1-D array is the 2-D table with rows overwritten in place; dp[j] before the update means dp[i-1][j].\n- It is a path-in-a-grid problem: right steps use b, down steps use a.", "cx": "Time O(nm), space O(m) (O(nm) for the 2-D version).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]},
    {"id": "cs2-wraparound-substrings", "title": "Unique substrings in a wraparound string", "cat": "Strings: sequence alignment and compression", "q": ["what is unique substrings in wraparound string", "explain unique substrings in wraparound string", "how does unique substrings in wraparound string work", "unique substrings in wraparound string in python", "implement unique substrings in wraparound string", "unique substrings in wraparound string code", "when to use unique substrings in wraparound string", "leetcode 467", "count distinct substrings of cyclic alphabet"], "tags": "unique substrings wraparound string alphabet abcdefghijklmnopqrstuvwxyz leetcode 467 consecutive letters cyclic z to a", "a": "Count the distinct non-empty substrings of s that appear in the infinite string \"...abc...xyzabc...\". A substring qualifies when each letter is the next letter of the previous (z wraps to a). For each ending letter keep the longest valid run ending there: that many distinct substrings end in that letter, so sum the 26 maxima.", "code": {"py": "def unique_wraparound_substrings(s):\n    best = [0] * 26                               # best[k]: longest valid run ending with letter k\n    run = 0\n    for i, ch in enumerate(s):\n        run = run + 1 if i and (ord(ch) - ord(s[i - 1])) % 26 == 1 else 1\n        k = ord(ch) - 97\n        best[k] = max(best[k], run)\n    return sum(best)\n\nprint(unique_wraparound_substrings(\"zab\"))  # 6"}, "check": "import random\nassert unique_wraparound_substrings(\"zab\") == 6 and unique_wraparound_substrings(\"cac\") == 2\nassert unique_wraparound_substrings(\"\") == 0\nfor _ in range(500):\n    s = \"\".join(random.choice(\"abcxyz\") for _ in range(random.randint(0, 10)))\n    subs = {s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)\n            if all((ord(s[k + 1]) - ord(s[k])) % 26 == 1 for k in range(i, j - 1))}\n    assert unique_wraparound_substrings(s) == len(subs), s", "more": "- A valid substring is determined by its last letter and its length; a run of length L ending in letter x contains valid substrings of every length 1..L ending in x, all distinct.\n- Taking the maximum run per letter removes duplicates across different places in s.\n- The wrap test is (cur - prev) % 26 == 1, which also handles z followed by a.\n- Assumes lowercase letters; adapt the modulus for other alphabets.", "cx": "Time O(n), space O(26).", "see": ["#/topic/string-dp", "#/cheatsheets/dp-catalog"]}
  );
})();
